insert into geological_assistant.modules (id,course_id,module_no,name,marks) values ('geological-assistant-m4','geological-assistant',4,'Petrology (Igneous, Metamorphic, Sedimentary)',20) on conflict (id) do update set name=excluded.name;
insert into geological_assistant.modules (id,course_id,module_no,name,marks) values ('geological-assistant-m5','geological-assistant',5,'Hydrogeology & Environmental Geology',20) on conflict (id) do update set name=excluded.name;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f001','geological-assistant','geological-assistant-m5','Groundwater quality - physical and chemical properties of water','Dissolved oxygen is low in stagnant ponds, deep wells and nutrient-rich (eutrophic) lakes, where decay uses oxygen faster than it is replaced.','Moving, turbulent water mixes with air and stays oxygen-rich. Still water does not.','Kerala PSC Assistant Geologist 2025',true,3,1,0) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f002','geological-assistant','geological-assistant-m2','Behaviour of minerals and rocks under deformation conditions','Rock strength increases with confining pressure and decreases as temperature rises.','Pressure presses cracks shut, so the rock is harder to break. Heat softens the rock so it flows more easily.','Kerala PSC Assistant Geologist 2025',true,3,1,1) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f003','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Ionic radius is the main control on substitution: ions of similar size (within about 15%) and balanced charge can replace one another in a crystal lattice (Goldschmidt''s rules).','Think of fitting a similar-sized brick into the same hole.','Kerala PSC Assistant Geologist 2025',true,3,1,2) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f004','geological-assistant','geological-assistant-m3','Mineral fuels','Coalification (peat to lignite to bituminous coal to anthracite) releases methane, carbon dioxide, nitrogen and water as by-products while the coal becomes richer in carbon.','The coal loses its volatile parts and keeps the carbon.','Kerala PSC Assistant Geologist 2025',true,3,1,3) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f005','geological-assistant','geological-assistant-m3','Mineral fuels','Most of the methane in a coal seam is held by adsorption on the internal surfaces of coal micropores, not as free gas; lowering the pressure by pumping out water releases it.','Gas molecules stick on the organic surface like a film.','Kerala PSC Assistant Geologist 2025',true,3,1,4) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f006','geological-assistant','geological-assistant-m3','Ceramic, refractory and industrial minerals','Fire clay (refractory clay) withstands temperatures of about 1500 C and above because of its high alumina content; fluxes such as iron oxide, lime and alkalis lower this resistance.','Alumina melts at a very high temperature, so alumina-rich clay is heat-proof.','Kerala PSC Assistant Geologist 2025',true,3,1,5) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f007','geological-assistant','geological-assistant-m3','Ore identification and beneficiation','Scheelite (CaWO4) and many uranium minerals fluoresce under ultraviolet light, so UV lamps are used for night prospecting and sorting of tungsten ore.','Scheelite glows bright blue-white under short-wave UV.','Kerala PSC Assistant Geologist 2025',true,3,1,6) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f008','geological-assistant','geological-assistant-m3','Mineral fuels','Gas hydrate is an ice-like water cage around gas molecules. Methane, ethane, CO2 and H2S form structure I; larger propane and isobutane form structure II.','Bigger guest molecules need bigger cages.','Kerala PSC Assistant Geologist 2025',false,3,1,7) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f009','geological-assistant','geological-assistant-m3','Iron and ferro-alloy metals','Taconite is a hard, low-grade banded iron formation of the Lake Superior region, made of magnetite (or hematite), iron silicates and chert, which is crushed and pelletised before smelting.','Taconite is the American name for low-grade BIF ore.','Kerala PSC Assistant Geologist 2025',true,3,1,8) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f010','geological-assistant','geological-assistant-m3','Classification and genesis of mineral deposits','Placers form by winnowing (elutriation): running water or waves wash away the light grains and leave heavy, resistant minerals such as gold, cassiterite, ilmenite and monazite behind.','Like washing rice: light bits float off, heavy bits stay.','Kerala PSC Assistant Geologist 2025',true,3,1,9) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f011','geological-assistant','geological-assistant-m3','Iron and ferro-alloy metals','Deep-sea manganese nodules are concentric layers of manganese and iron oxides (such as todorokite and birnessite) around a small nucleus, and they carry nickel, copper and cobalt.','They grow very slowly, like layers of an onion, around a shark tooth or rock fragment.','Kerala PSC Assistant Geologist 2025',true,3,1,10) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f012','geological-assistant','geological-assistant-m3','Controls of mineral localisation','Chromium, nickel and platinum-group metals are tied to ultramafic rocks, whereas tin and tungsten are tied to granites.','Ultramafic magma is rich in Mg, Fe, Cr, Ni. Granite melts concentrate Sn, W, Li.','Kerala PSC Assistant Geologist 2025',true,3,1,11) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f013','geological-assistant','geological-assistant-m3','Classification and genesis of mineral deposits','Rare-metal (lithium-caesium-tantalum) pegmatites crystallise from melts rich in volatiles (water, fluorine, boron, phosphorus) and incompatible elements such as Li, Cs, Ta and Be.','Volatiles make the melt runny, so crystals grow giant.','Kerala PSC Assistant Geologist 2025',true,3,1,12) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f014','geological-assistant','geological-assistant-m3','Classification and genesis of mineral deposits','The massive ore of volcanogenic massive sulphide (VMS) deposits is dominated by pyrite, with chalcopyrite as the main copper mineral (sphalerite and galena in zinc-lead types).','VMS = pyrite-rich sea-floor sulphide mound.','Kerala PSC Assistant Geologist 2025',true,3,1,13) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f015','geological-assistant','geological-assistant-m2','Stratigraphic principles and correlation','By the law of superposition, in an undisturbed sequence of sedimentary layers the lowest bed is the oldest and the topmost bed is the youngest.','Steno''s law: you lay new layers on top of old ones.','Kerala PSC Assistant Geologist 2025',true,3,1,14) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f016','geological-assistant','geological-assistant-m1','Topographical maps','A map is a scaled, two-dimensional representation of part of the Earth''s surface; its scale is the ratio of map distance to ground distance.','Scale 1:50,000 means 1 cm on the map is 50,000 cm (0.5 km) on the ground.','Kerala PSC Assistant Geologist 2025',true,3,1,15) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f017','geological-assistant','geological-assistant-m5','Water-bearing properties of rocks','Volcanic rock permeability varies: vesicular, jointed or rubbly-topped basalt can be a good aquifer, but dense massive lava (basalt or rhyolite) is nearly tight; unweathered igneous and metamorphic rocks are generally tight.','Permeability comes from vesicles, joints, rubbly flow tops and lava tubes, not from rock name.','Kerala PSC Junior Hydrogeologist 2023',false,3,1,16) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f018','geological-assistant','geological-assistant-m5','Hydrologic cycle and water budget','A neutron probe measures soil moisture: fast neutrons from a source are slowed and scattered by hydrogen in soil water, and the count of slowed neutrons gives the water content.','Hydrogen (in water) is the best neutron slower.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,17) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f019','geological-assistant','geological-assistant-m5','Groundwater provinces and problems','The Indo-Gangetic alluvium is India''s most productive aquifer system: thick sand-gravel beds, river, canal and rainfall recharge give very high yields and large groundwater resources.','Think thick, loose sand-gravel plus big rivers.','Kerala PSC Junior Hydrogeologist 2023',false,3,1,18) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f020','geological-assistant','geological-assistant-m5','Hydrologic cycle and water budget','Evaporation absorbs about 590 calories per gram of water (latent heat of vaporisation near 15 C, about 2.47 MJ/kg) and continues until the air above is saturated.','This heat comes from the water and surroundings, which is why evaporation cools.','Kerala PSC Junior Hydrogeologist 2023',false,3,1,19) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f021','geological-assistant','geological-assistant-m5','Specific yield, specific retention, porosity, hydraulic conductivity, transmissivity, storage coefficient','For equal spheres, cubic packing gives the highest porosity (about 47.6%) and rhombohedral packing the lowest (about 26%).','Rhombohedral packing nests spheres into each other''s hollows.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,20) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f022','geological-assistant','geological-assistant-m5','Specific yield, specific retention, porosity, hydraulic conductivity, transmissivity, storage coefficient','A formation is isotropic if its hydraulic conductivity is the same in every direction at a point; it is anisotropic if the value changes with direction (in layered sediments horizontal K exceeds vertical K).','Isotropic = same in all directions. Homogeneous = same at all places.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,21) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f023','geological-assistant','geological-assistant-m5','Theory of groundwater flow','The Bernoulli equation assumes ideal flow: the fluid is non-viscous (frictionless) and incompressible; groundwater velocity is so low that the velocity head is ignored.','Real flow in pores loses energy to friction, so Darcy''s law is used instead.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,22) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f024','geological-assistant','geological-assistant-m5','Theory of groundwater flow','A contact between an aquifer sand and a thick clay bed acts as an impermeable (barrier) boundary, whereas a river or lake in contact with the aquifer acts as a recharge boundary.','Clay blocks water, a river supplies it.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,23) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f025','geological-assistant','geological-assistant-m5','Water-bearing properties of rocks','In crystalline rocks fractures and weathering are strongest near the surface, with sheet joints running parallel to it, so fracture density, aperture and permeability fall with depth.','Overburden load closes fractures at depth.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,24) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f026','geological-assistant','geological-assistant-m5','Water-bearing properties of rocks','In carbonate rocks, burial compaction, cementation and recrystallisation change porosity and permeability (mostly reducing the primary pores), while later dissolution creates secondary porosity.','Diagenesis can close pores; dissolution reopens them.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,25) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f027','geological-assistant','geological-assistant-m5','Concepts of drainage basin and groundwater basin','A groundwater divide is a crest (ridge) of the water table or potentiometric surface from which groundwater flows away in opposite directions.','It is the underground equivalent of a ridge line.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,26) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f028','geological-assistant','geological-assistant-m5','Theory of groundwater flow','Flow is in steady state when conditions, and so the stored mass of water, do not change with time; if any property such as head or temperature changes with time, the system is unsteady (transient).','Steady = nothing changes with time. Transient = something does.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,27) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f029','geological-assistant','geological-assistant-m5','Types of wells and well construction','Bored wells are made with hand or rotary augers in soft ground; they are shallow, commonly up to about 30 m deep (limit varies by textbook).','Auger = a big screw that bores into soil.','Kerala PSC Junior Hydrogeologist 2023',false,3,1,28) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f030','geological-assistant','geological-assistant-m5','Natural hazards - landslides','In the Standard Penetration Test, the N value is the number of blows of a 63.5 kg hammer needed to drive the split-spoon sampler through the last 300 mm of a 450 mm drive.','N tells how dense or stiff a soil is. Engineering-geology item, outside the listed syllabus.','Kerala PSC Junior Hydrogeologist 2023',false,3,1,29) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f031','geological-assistant','geological-assistant-m5','Groundwater exploration - geophysical methods','In seismic refraction surveys, geophones placed on the ground detect waves refracted from layer boundaries; travel-time curves give layer velocities and depth to hard rock.','Geophone = ground microphone.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,30) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f032','geological-assistant','geological-assistant-m5','Groundwater exploration - geophysical methods','In neutron-capture (pulsed-neutron) logging, chlorine in saline water has a high thermal-neutron capture cross-section, so a high capture reading points to a saline water-bearing formation.','Chlorine absorbs slow neutrons strongly.','Kerala PSC Junior Hydrogeologist 2023',false,3,1,31) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f033','geological-assistant','geological-assistant-m5','Water-bearing properties of rocks','Sandstone shows a very wide range of water yield: weakly cemented, well-sorted sandstone is an excellent aquifer, but tightly cemented or clay-rich sandstone is almost tight unless fractured.','Cement and clay fill the pores.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,32) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f034','geological-assistant','geological-assistant-m5','Well design, development and maintenance','Well points, vacuum methods and electro-osmosis are used to lower the water table (dewatering) at construction sites; electro-osmosis suits fine-grained silts and clays.','Electric current drags water through very fine pores.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,33) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f035','geological-assistant','geological-assistant-m5','Groundwater quality - criteria for different uses','Contaminated drinking water spreads diarrhoea, cholera, typhoid, hepatitis A and polio; polluted water is the main cause of water-borne disease in India.','These diseases pass by the faecal-oral route.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,34) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f036','geological-assistant','geological-assistant-m5','Artificial recharge and groundwater management','During artificial recharge the soil and aquifer material act as a natural filter, removing suspended matter and bacteria as water percolates down.','This is called soil-aquifer treatment.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,35) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f037','geological-assistant','geological-assistant-m5','Groundwater quality - physical and chemical properties of water','Alkalinity of water, caused mainly by bicarbonate, carbonate and hydroxide, is reported in mg/L as equivalent calcium carbonate (CaCO3).','Hardness is also reported as CaCO3.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,36) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f038','geological-assistant','geological-assistant-m5','Groundwater provinces and problems','India is the world''s largest user of groundwater, abstracting roughly a quarter of the global total, mostly for irrigation.','Ahead of China and the USA.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,37) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f039','geological-assistant','geological-assistant-m1','Geomorphology of Kerala / India','Munnar, in Idukki district at about 1,500 m, is an example of a plateau (the high-range upland) in the Western Ghats of Kerala.','Kerala has highland, midland and lowland zones; Munnar is highland.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,38) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-pp-f040','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The crystalline basement rocks of Kerala (charnockite, gneiss and khondalite) are Precambrian, mainly Archaean to Proterozoic in age.','They are the oldest rocks of the state; sedimentary rocks are only Tertiary and Quaternary.','Kerala PSC Junior Hydrogeologist 2023',true,3,1,39) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f001','geological-assistant','geological-assistant-m1','Earth and the solar system','The nebular hypothesis (Kant and Laplace) says the Sun and planets formed from one rotating cloud of gas and dust; it is the most widely accepted model.','A spinning cloud flattens into a disc. This explains why all planets orbit in the same direction and nearly the same plane.','UPSC Combined Geo-Scientist Prelims 2021 (Geology Paper II)',true,3,1,40) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f002','geological-assistant','geological-assistant-m1','Earth and the solar system','Mercury, Venus, Earth and Mars are terrestrial (rocky, dense) planets; Jupiter, Saturn, Uranus and Neptune are Jovian (large, low-density) planets. The asteroid belt lies between Mars and Jupiter.','Near the hot young Sun only rock and metal could condense. Farther out, gas and ice could collect, making giant planets.',null,true,2,2,41) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f003','geological-assistant','geological-assistant-m1','Earth and the solar system','The Earth is about 4.55 billion years old, an age first fixed by Clair Patterson (1956) from lead isotopes in meteorites.','Earth''s first rocks were destroyed by later melting and recycling. Meteorites formed at the same time and stayed unchanged, so they give the true age.',null,true,3,1,42) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f004','geological-assistant','geological-assistant-m1','Earth and the solar system','Meteorites are stony, iron or stony-iron; stony chondrites are the most common falls, and iron meteorites show the Widmanstatten pattern.','Iron meteorites are pieces of broken asteroid cores, so they hint at what Earth''s core is made of. The pattern is an intergrowth of two iron-nickel alloys.',null,true,2,2,43) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f005','geological-assistant','geological-assistant-m1','Earth and the solar system','Hydrogen is the most abundant element in the solar system, followed by helium and then oxygen.','The Sun holds almost all the mass of the solar system and it is mostly hydrogen and helium.','IIT JAM Geology 2024',true,2,2,44) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f006','geological-assistant','geological-assistant-m1','Earth and the solar system','The mean density of the Earth is about 5.5 g/cm3, the highest of all planets, while surface rocks average only about 2.7 to 3.0 g/cm3.','The gap proves the interior must be much denser than the crust. This was early evidence for a heavy iron core.',null,true,3,1,45) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f007','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','Early Earth melted and differentiated: dense iron and nickel sank to form the core, and lighter silicates rose to form the mantle and crust.','Heavy things sink and light things float in a molten body. This sorting is called differentiation (the ''iron catastrophe'').',null,true,2,2,46) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f008','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','P waves are compressional, the fastest, and travel through solids, liquids and gases; S waves are shear waves, slower, and travel only through solids.','Liquids cannot resist a change of shape (no rigidity), so a shear wave dies in them. P = primary/push, S = secondary/shake.',null,true,3,1,47) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f009','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','Love and Rayleigh waves are surface waves; they are slower than P and S waves but cause the most damage. Love waves are faster than Rayleigh waves.','Surface waves keep their energy near the ground and have large amplitude. Rayleigh waves roll the ground like sea waves; Love waves shake it sideways.',null,true,3,1,48) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f010','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','The Mohorovicic discontinuity (Moho) separates crust from mantle; P-wave velocity jumps there to about 8 km/s. It was discovered in 1909 from a Croatian earthquake.','Mantle peridotite is denser and stiffer than crustal rock, so waves speed up suddenly on entering it.',null,true,3,1,49) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f011','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','The Conrad discontinuity separates the upper granitic continental crust (sial) from the lower basaltic crust (sima).','It lies inside the continental crust, above the Moho. It is weak and not found everywhere, and is absent under oceans.','UPSC Combined Geo-Scientist Prelims 2021 (Geology Paper II)',true,3,1,50) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f012','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','The Gutenberg discontinuity at about 2,900 km depth separates the mantle from the outer core; P-wave velocity drops sharply and S waves stop.','The waves pass from solid rock into liquid iron. Liquid has no rigidity, so S waves vanish and P waves slow down.',null,true,3,1,51) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f013','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','The Lehmann discontinuity at about 5,150 km depth separates the liquid outer core from the solid inner core; Inge Lehmann found it in 1936.','She saw weak P waves arriving inside the shadow zone. They had bounced off a solid inner core. Huge pressure keeps the inner core solid.',null,true,3,1,52) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f014','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','The Repetti discontinuity separates upper and lower mantle; most Indian texts place it near 700 km (modern value 660 km), some older texts near 1,000 km.','Memory order from top to bottom: Conrad, Moho, Repetti, Gutenberg, Lehmann (''Can My Rabbit Go Low'').',null,false,2,2,53) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f015','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','The P-wave shadow zone lies roughly between 105 and 145 degrees from the epicentre; direct S waves are absent beyond about 105 degrees.','The liquid outer core bends (refracts) P waves and blocks S waves. The shadow zones are the main proof of a liquid outer core.',null,true,3,1,54) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f016','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','R.D. Oldham of the Geological Survey of India gave the first seismic evidence for the Earth''s core in 1906; Gutenberg later fixed its depth.','Oldham studied records of the 1897 Assam earthquake and first separated P, S and surface waves. Link: Oldham = ''old'' = first to find the core.',null,true,2,2,55) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f017','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','The low velocity zone (LVZ), at roughly 100 to 250 km depth, marks the upper asthenosphere, where seismic waves slow down.','The rock here is close to melting and has a tiny amount of melt, so it is weak and plastic. Rigid plates slide over this soft layer.',null,true,3,1,56) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f018','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','The lithosphere is the rigid outer shell made of the crust plus the uppermost mantle, about 100 km thick on average; it is broken into plates.','Crust and mantle are divided by composition. Lithosphere and asthenosphere are divided by strength (rigid versus plastic). Plates are lithosphere, not just crust.',null,true,3,1,57) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f019','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','The core is mainly iron with some nickel; flow in the liquid outer core generates the Earth''s magnetic field (geodynamo).','Moving liquid metal carries electric currents, and currents make a magnetic field. The solid inner core cannot flow, so the outer core does this job.',null,true,3,1,58) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f020','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','The upper mantle is peridotite (olivine and pyroxene). The 410 km discontinuity is a phase change of olivine to a denser spinel-type structure.','Pressure squeezes olivine into a tighter crystal packing without changing its chemistry. At 660 km it changes again to still denser lower-mantle minerals.','UPSC Combined Geo-Scientist Mains 2020 (Geology Paper II)',true,2,2,59) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f021','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','Suess named the Earth''s layers by composition: SIAL (silica and aluminium, continental crust), SIMA (silica and magnesium, oceanic and lower crust) and NIFE (nickel and iron, core).','Each name is built from the chemical symbols of its main elements: Si+Al, Si+Mg, Ni+Fe.',null,true,3,1,60) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f022','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','The average geothermal gradient in the upper crust is about 25 to 30 degrees C per km of depth.','Heat flows out from the hot interior and from radioactive decay in crustal rocks. The gradient is higher at ridges and volcanoes, lower in old shields.','IIT JAM Geology 2024',true,2,2,61) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f023','geological-assistant','geological-assistant-m1','Planetary evolution of the earth and its internal structure','By weight, the crust''s most abundant elements are oxygen, silicon, aluminium and iron, in that order; for the whole Earth, iron is first and oxygen second.','The crust is made of silicate minerals (O + Si). The whole Earth includes the huge iron core, so iron moves to the top.',null,true,3,1,62) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f024','geological-assistant','geological-assistant-m1','Heterogeneity of the earth''s crust','Continental crust is thick (average about 35 to 40 km, up to about 70 km under Tibet), granitic and light (2.7 g/cm3); oceanic crust is thin (about 7 km), basaltic and denser (3.0 g/cm3).','Light continental crust floats high and cannot sink into the mantle. Dense oceanic crust sits low and is the one that subducts.',null,true,3,1,63) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f025','geological-assistant','geological-assistant-m1','Heterogeneity of the earth''s crust','No oceanic crust is older than about 180 million years (Jurassic), but continental rocks are as old as about 4 billion years.','Old ocean floor is destroyed at subduction zones, so it is always young. Continents are too light to subduct, so they keep very old rocks.',null,true,3,1,64) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f026','geological-assistant','geological-assistant-m1','Heterogeneity of the earth''s crust','Oceanic crust has three seismic layers: layer 1 sediments, layer 2 pillow basalts and sheeted dykes, and layer 3 gabbro, resting on mantle peridotite.','Magma at a ridge erupts on the sea floor as pillow lava, feeds through dykes, and the rest cools slowly below as gabbro.',null,true,2,2,65) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f027','geological-assistant','geological-assistant-m1','Heterogeneity of the earth''s crust','An ophiolite is a slice of oceanic lithosphere thrust onto land; Indian examples occur along the Indus-Tsangpo suture (Ladakh), the Naga Hills and the Andaman Islands.','Ophiolites mark where an old ocean closed. Finding one in a mountain belt means a vanished ocean and a suture (join) between plates.','UPSC Combined Geo-Scientist Prelims 2021 (Geology Paper II); UPSC Combined Geo-Scientist Mains 2020 (Geology Paper II)',true,3,1,66) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f028','geological-assistant','geological-assistant-m1','Major tectonic features of the Oceanic and Continental crust','A craton is the old, stable interior of a continent; it consists of a shield (exposed Precambrian basement) and a platform (basement under flat sedimentary cover).','Cratons have not been folded for a very long time. Peninsular India is a shield area made of several cratons such as Dharwar and Bastar.',null,true,2,2,67) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f029','geological-assistant','geological-assistant-m1','Major tectonic features of the Oceanic and Continental crust','The mid-ocean ridge system is the longest mountain chain on Earth, about 65,000 km long. Slow ridges (Mid-Atlantic) have a central rift valley; fast ridges (East Pacific Rise) are smooth.','At slow ridges the crust is cooler and breaks along faults, making a valley. At fast ridges plenty of hot magma keeps the crest swollen and smooth.',null,true,2,2,68) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f030','geological-assistant','geological-assistant-m1','Major tectonic features of the Oceanic and Continental crust','Deep-sea trenches mark subduction zones; the deepest point on Earth is the Challenger Deep in the Mariana Trench (about 11 km), western Pacific. Guyots are flat-topped seamounts.','A trench forms where a plate bends and dives down. Guyots are old volcanic islands planed flat by waves and later sunk; Hess named them.',null,true,3,1,69) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f031','geological-assistant','geological-assistant-m1','Major tectonic features of the Oceanic and Continental crust','Passive (Atlantic-type) continental margins are not plate boundaries and have few earthquakes; active (Pacific-type) margins have trenches, volcanoes and earthquakes. Both coasts of India are passive margins.','At a passive margin the continent and the ocean floor belong to the same plate, so nothing grinds. At an active margin the ocean plate subducts.',null,true,2,2,70) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f032','geological-assistant','geological-assistant-m1','Major tectonic features of the Oceanic and Continental crust','A triple junction is a point where three plates meet, as at Afar (Red Sea, Gulf of Aden, East African Rift); a failed rift arm is called an aulacogen.','A dome over hot mantle cracks into three arms. Usually two arms open into an ocean and the third stops and fills with sediment.',null,true,2,2,71) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f033','geological-assistant','geological-assistant-m1','Continental drift - geological and geophysical evidence, mechanics, objections, present status','Alfred Wegener proposed continental drift in 1912 and published ''The Origin of Continents and Oceans'' in 1915; his supercontinent Pangaea was surrounded by the ocean Panthalassa.','Pangaea means ''all land'' and Panthalassa means ''all sea''. Wegener was a German meteorologist, not a geologist.',null,true,3,1,72) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f034','geological-assistant','geological-assistant-m1','Continental drift - geological and geophysical evidence, mechanics, objections, present status','Pangaea split into Laurasia in the north and Gondwanaland in the south, separated by the Tethys Sea.','Gondwanaland held South America, Africa, India, Australia and Antarctica. The Tethys later closed to form the Alps and Himalaya.',null,true,3,1,73) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f035','geological-assistant','geological-assistant-m1','Continental drift - geological and geophysical evidence, mechanics, objections, present status','The jigsaw fit of South America and Africa is best along the continental slope, not the coastline, as Bullard''s 1965 computer fit showed.','The true edge of a continent is under water, at the slope. Coastlines change with sea level, so they fit poorly.',null,true,3,1,74) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f036','geological-assistant','geological-assistant-m1','Continental drift - geological and geophysical evidence, mechanics, objections, present status','Fossil evidence for drift: the seed fern Glossopteris on all Gondwana continents, the freshwater reptile Mesosaurus in Brazil and South Africa, and the land reptile Lystrosaurus in Africa, India and Antarctica.','These plants and animals could not cross wide salty oceans. So the lands must once have been joined.','UPSC Combined Geo-Scientist Mains 2020 (Geology Paper II)',true,3,1,75) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f037','geological-assistant','geological-assistant-m1','Continental drift - geological and geophysical evidence, mechanics, objections, present status','Permo-Carboniferous glacial deposits (tillites) occur in South America, Africa, India, Australia and Antarctica; in India this is the Talchir boulder bed.','Ice cannot form at the equator at sea level. These lands must have been together near the South Pole at that time.',null,true,3,1,76) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f038','geological-assistant','geological-assistant-m1','Continental drift - geological and geophysical evidence, mechanics, objections, present status','Wegener said drift was driven by a pole-fleeing force and tidal force; Harold Jeffreys objected that these forces are far too weak.','This lack of a working mechanism was the main reason the theory was rejected for decades. Wegener also wrongly had continents ploughing through ocean floor.',null,true,3,1,77) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f039','geological-assistant','geological-assistant-m1','Continental drift - geological and geophysical evidence, mechanics, objections, present status','Arthur Holmes (around 1930) proposed that thermal convection currents in the mantle carry the continents.','Hot mantle rises, spreads sideways and sinks, like boiling soup. This gave drift its first workable engine, later used in sea-floor spreading.',null,true,3,1,78) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f040','geological-assistant','geological-assistant-m1','Continental drift - geological and geophysical evidence, mechanics, objections, present status','F.B. Taylor suggested drift in 1910 to explain mountain belts; Alexander du Toit supported Wegener in ''Our Wandering Continents'' (1937).','Du Toit, a South African geologist, matched rocks of South Africa and South America in detail. Taylor came before Wegener but had little evidence.',null,true,2,2,79) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f041','geological-assistant','geological-assistant-m1','Continental drift - geological and geophysical evidence, mechanics, objections, present status','Present status: drift is accepted as part of plate tectonics; continents ride passively on lithospheric plates, and motions of a few cm per year are measured directly by GPS.','Palaeomagnetism and sea-floor spreading in the 1950s and 1960s revived the idea. The continents do not plough through the sea floor; the whole plate moves.',null,true,2,2,80) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f042','geological-assistant','geological-assistant-m1','Gravity and magnetic anomalies at Mid-ocean ridges, deep sea trenches, continental shield areas and mountain chains','Bouguer gravity anomalies are strongly negative over high mountain chains and positive over deep oceans.','Mountains have deep roots of light crust (mass deficit below). Under oceans, dense mantle lies close to the surface (mass excess).',null,true,3,1,81) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f043','geological-assistant','geological-assistant-m1','Gravity and magnetic anomalies at Mid-ocean ridges, deep sea trenches, continental shield areas and mountain chains','Deep-sea trenches show very large negative free-air gravity anomalies, first measured by Vening Meinesz in a submarine; the adjacent island arc shows a positive anomaly.','The trench is a deep hole filled with light water and sediment, held down by the sinking plate. It is not in isostatic balance.','UPSC Combined Geo-Scientist Mains 2020 (Geology Paper II)',true,3,1,82) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f044','geological-assistant','geological-assistant-m1','Gravity and magnetic anomalies at Mid-ocean ridges, deep sea trenches, continental shield areas and mountain chains','Over mid-ocean ridges the free-air gravity anomaly is close to zero, and the Bouguer anomaly is lower over the crest than over the flanks.','The ridge stands high because hot, light mantle lies below it. The extra height is balanced by the low density beneath (isostatic compensation).',null,true,2,2,83) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f045','geological-assistant','geological-assistant-m1','Gravity and magnetic anomalies at Mid-ocean ridges, deep sea trenches, continental shield areas and mountain chains','Shield areas once covered by ice sheets (Canada, Fennoscandia) show negative gravity anomalies and are still rising, a process called post-glacial rebound.','The ice pushed the crust down. The ice melted fast but the thick mantle flows back slowly, so the land is still rising. This is isostasy in action.',null,true,2,2,84) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f046','geological-assistant','geological-assistant-m1','Gravity and magnetic anomalies at Mid-ocean ridges, deep sea trenches, continental shield areas and mountain chains','Magnetic anomalies on the ocean floor form linear stripes, parallel to and symmetric about the mid-ocean ridge; Vine and Matthews (and Morley) explained them in 1963.','New basalt at the ridge records the field direction of its time. The field reverses and the floor spreads both ways, giving mirror-image stripes.','UPSC Combined Geo-Scientist Mains 2020 (Geology Paper II)',true,3,1,85) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f047','geological-assistant','geological-assistant-m1','Palaeomagnetism','The Curie point is the temperature above which a mineral loses its permanent magnetism; it is about 580 degrees C for magnetite and about 680 degrees C for hematite.','Heat shakes the atoms so their tiny magnets cannot stay lined up. Magnetite is the chief magnetic mineral in rocks.',null,true,3,1,86) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f048','geological-assistant','geological-assistant-m1','Palaeomagnetism','Lavas gain thermoremanent magnetism (TRM) on cooling below the Curie point; sediments gain detrital remanent magnetism (DRM) as magnetic grains settle and align.','TRM is strong and stable, so basalts are the best recorders. A third type, chemical (CRM), forms when magnetic minerals grow in the rock.',null,true,2,2,87) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f049','geological-assistant','geological-assistant-m1','Palaeomagnetism','Palaeolatitude is found from magnetic inclination I using tan I = 2 tan (latitude); inclination is 0 degrees at the magnetic equator and 90 degrees at the poles.','A compass needle free to tilt lies flat at the equator and points straight down at the pole. The frozen tilt in a rock tells where it formed.',null,true,3,1,88) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f050','geological-assistant','geological-assistant-m1','Palaeomagnetism','Apparent polar wander (APW) paths differ from continent to continent, which shows the continents moved, not the pole; Runcorn showed this for Europe and North America in the 1950s.','The Earth has only one north magnetic pole at a time. Two different paths can only be merged by moving the continents back together.',null,true,3,1,89) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f051','geological-assistant','geological-assistant-m1','Palaeomagnetism','The present normal polarity chron is the Brunhes; before it came the reversed Matuyama chron. The Brunhes-Matuyama boundary is about 0.78 million years old.','Order going back in time: Brunhes (normal), Matuyama (reversed), Gauss (normal), Gilbert (reversed). Hook: ''Big Men Get Going''.',null,true,3,1,90) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f052','geological-assistant','geological-assistant-m1','Seafloor spreading and Plate Tectonics','Harry Hess proposed sea-floor spreading (''History of Ocean Basins'', 1962); Robert Dietz coined the term ''sea-floor spreading'' in 1961.','New ocean floor forms at ridges, moves away like a conveyor belt and is destroyed at trenches. Hess called his own idea ''geopoetry''.',null,true,3,1,91) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f053','geological-assistant','geological-assistant-m1','Seafloor spreading and Plate Tectonics','J. Tuzo Wilson introduced the hotspot idea (1963), transform faults (1965) and the Wilson cycle of opening and closing of ocean basins.','One name, three big ideas. A transform fault links two offset ridge segments and lets plates slide past each other.',null,true,3,1,92) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f054','geological-assistant','geological-assistant-m1','Seafloor spreading and Plate Tectonics','Plate tectonics was formulated in 1967-68 by Morgan, McKenzie and Parker, and Le Pichon; the Pacific is the largest plate.','It grew out of Hess''s seafloor spreading (1962) and Wilson''s transform faults (1965).',null,true,2,2,93) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f055','geological-assistant','geological-assistant-m1','Seafloor spreading and Plate Tectonics','Plate boundaries are divergent (constructive, e.g. Mid-Atlantic Ridge), convergent (destructive, e.g. Andes) and transform (conservative, e.g. San Andreas Fault).','Crust is made at divergent, destroyed at convergent, and neither made nor destroyed at transform boundaries. San Andreas is a right-lateral fault.','UPSC Combined Geo-Scientist Mains 2020 (Geology Paper II)',true,3,1,94) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f056','geological-assistant','geological-assistant-m1','Seafloor spreading and Plate Tectonics','Convergence is of three kinds: ocean-ocean (Mariana, Japan: island arcs), ocean-continent (Andes: continental volcanic arc) and continent-continent (Himalaya, Alps: fold mountains without active volcanoes).','Volcanoes need a sinking ocean plate to release water and melt the mantle. In continent-continent collision nothing subducts deeply, so volcanism stops.',null,true,3,1,95) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f057','geological-assistant','geological-assistant-m1','Seafloor spreading and Plate Tectonics','The main forces that move plates are slab pull, ridge push and mantle drag; slab pull is the strongest.','The cold, dense plate sinking at a trench pulls the rest of the plate behind it. Plates with long subducting edges (Pacific) move fastest.',null,true,3,1,96) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f058','geological-assistant','geological-assistant-m1','Seafloor spreading and Plate Tectonics','Wilson cycle stages with examples: embryonic (East African Rift), juvenile (Red Sea), mature (Atlantic), declining (Pacific), terminal (Mediterranean) and suture (Himalaya).','An ocean is born from a rift, widens, then shrinks by subduction and finally closes in a collision. Each stage has a living example today.',null,true,2,2,97) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f059','geological-assistant','geological-assistant-m1','Seafloor spreading and Plate Tectonics','Black smokers are hydrothermal vents at mid-ocean ridges where hot, metal sulphide-rich water jets into cold sea water.','Sea water seeps into hot new crust, picks up metals and returns. On meeting cold water the sulphides fall out as black ''smoke''.','UPSC Combined Geo-Scientist Prelims 2021 (Geology Paper II)',true,2,2,98) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f060','geological-assistant','geological-assistant-m1','Seismicity and plate movements','The world''s largest earthquakes are megathrust events on the contact between the subducting and overriding plates; the largest recorded is Chile 1960 (Mw 9.5).','This contact is a huge, gently dipping fault surface. A bigger rupture area gives a bigger earthquake, and it often lifts the sea floor to cause tsunamis.','UPSC Combined Geo-Scientist Prelims 2021 (Geology Paper II)',true,3,1,99) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f061','geological-assistant','geological-assistant-m1','Island arcs, Oceanic islands and volcanic arcs','The Wadati-Benioff zone is the inclined zone of earthquake foci that follows a subducting slab down to about 700 km depth.','The cold sinking plate stays brittle and keeps breaking as it goes down. Plotting the foci draws the shape of the slab.','IIT JAM Geology 2024',true,3,1,100) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f062','geological-assistant','geological-assistant-m1','Island arcs, Oceanic islands and volcanic arcs','An island arc is a curved chain of volcanic islands on the overriding plate, parallel to a trench and convex towards the ocean; examples are Japan, the Aleutians, the Marianas and the Andaman-Sunda arc.','It forms at ocean-ocean convergence. The arc shape comes from a flat slab bending into a sphere, like a dent in a ping-pong ball.',null,true,3,1,101) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f063','geological-assistant','geological-assistant-m1','Island arcs, Oceanic islands and volcanic arcs','Andesite is the typical lava of volcanic arcs above subduction zones; the ''Andesite Line'' around the Pacific separates basaltic ocean-floor volcanoes from andesitic marginal ones.','Water from the sinking slab melts the mantle wedge, and the magma changes on its way up through the crust. Ridges and ocean islands give basalt instead.',null,true,3,1,102) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f064','geological-assistant','geological-assistant-m1','Island arcs, Oceanic islands and volcanic arcs','From ocean to land, an arc-trench system has: trench, accretionary prism, fore-arc basin, volcanic arc and back-arc basin. The Andaman Sea and the Sea of Japan are back-arc basins.','The accretionary prism is sediment scraped off the sinking plate. Behind the arc the crust stretches and may open a small ocean (back-arc).',null,true,2,2,103) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f065','geological-assistant','geological-assistant-m1','Island arcs, Oceanic islands and volcanic arcs','The Hawaiian-Emperor chain is a hotspot track: islands get older towards the northwest, showing the Pacific plate moved northwest over a fixed mantle plume. Morgan proposed mantle plumes in 1971.','The plume stays put while the plate slides over it, like paper moved over a candle. The active volcanoes are at the young southeast end.',null,true,3,1,104) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f066','geological-assistant','geological-assistant-m1','Island arcs, Oceanic islands and volcanic arcs','Barren Island in the Andaman Sea is India''s only active volcano; nearby Narcondam is dormant. Both belong to the Andaman-Sunda volcanic arc.','The Indian plate subducts beneath the Burma plate here. The same arc continues south into the volcanoes of Sumatra and Java.',null,true,3,1,105) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f067','geological-assistant','geological-assistant-m1','Isostasy, orogeny and epeirogeny','The term ''isostasy'' was coined by the American geologist Clarence Dutton in 1889.','Isostasy means ''equal standing'': the crust floats in balance on the denser, plastic mantle, like wood blocks on water.',null,true,3,1,106) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f068','geological-assistant','geological-assistant-m1','Isostasy, orogeny and epeirogeny','Airy''s model: crustal blocks have the same density but different thickness, so high mountains have deep roots.','Like icebergs: the taller the block, the deeper it sinks. Seismic studies confirm thick crust under mountains. Hook: Airy = roots.',null,true,3,1,107) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f069','geological-assistant','geological-assistant-m1','Isostasy, orogeny and epeirogeny','Pratt''s model: crustal blocks have different densities but reach down to one uniform level of compensation; higher blocks are made of lighter rock.','Pratt (Archdeacon of Calcutta) analysed Survey of India data: the deflection difference between Kaliana and Kalianpur was about 5 seconds of arc against 15 calculated. Hook: Pratt = density.',null,true,3,1,108) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f070','geological-assistant','geological-assistant-m1','Isostasy, orogeny and epeirogeny','Orogeny is mountain building in long narrow belts by folding, thrusting, metamorphism and magmatism; epeirogeny is broad, gentle uplift or sinking of large areas without much folding (term by G.K. Gilbert).','Oros = mountain, epeiros = mainland. Orogeny acts mostly sideways (compression); epeirogeny acts mostly up and down.',null,true,3,1,109) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f071','geological-assistant','geological-assistant-m1','Isostasy, orogeny and epeirogeny','Major orogenies in time order: Caledonian (Ordovician-Silurian to early Devonian), Hercynian or Variscan (Carboniferous-Permian) and Alpine-Himalayan (Cenozoic).','Alphabet hook: C, H, A in time order is ''CHA''. The Himalaya belong to the youngest, the Alpine cycle.','UPSC Combined Geo-Scientist Prelims 2021 (Geology Paper II)',true,3,1,110) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f072','geological-assistant','geological-assistant-m1','Isostasy, orogeny and epeirogeny','The geosyncline idea came from James Hall (1859) and the name from J.D. Dana (1873); it explained mountains as uplifted thick sediment troughs and is now replaced by plate tectonics.','It could not explain why the trough was squeezed. Plate collision supplies that sideways force.',null,true,2,2,111) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f073','geological-assistant','geological-assistant-m1','Seismic belts of the earth','Circum-Pacific belt releases about 80% of earthquake energy (about 68% of earthquakes by number in some Indian texts); Alpine-Himalayan belt is second (about 15-21%); mid-ocean ridges third.','The Pacific is ringed by subduction zones, which store and release the most strain. Ridges give only small, shallow shocks.',null,false,3,1,112) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f074','geological-assistant','geological-assistant-m1','Seismic belts of the earth','Earthquakes are classed by focal depth as shallow (0-70 km), intermediate (70-300 km) and deep (300-700 km); deep-focus earthquakes occur only in subduction zones.','Normal mantle at that depth is too hot and soft to break. Only a cold sinking slab is brittle enough.',null,true,3,1,113) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f075','geological-assistant','geological-assistant-m1','Seismic belts of the earth','Intraplate earthquakes occur far from plate boundaries, on old weak zones; the 1993 Latur (Killari) earthquake in Maharashtra, Mw 6.2, struck the stable Peninsular shield.','Plate-edge stress travels into the interior and reactivates ancient faults. Such quakes are rare but deadly because buildings are not designed for them.',null,true,3,1,114) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f076','geological-assistant','geological-assistant-m1','Seismic belts of the earth','The elastic rebound theory of earthquakes was given by H.F. Reid after the 1906 San Francisco earthquake.','Rocks on both sides of a fault bend slowly like a stick. When they snap and spring back, the stored energy is released as an earthquake.',null,true,3,1,115) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f077','geological-assistant','geological-assistant-m1','Seismic belts of the earth','Magnitude (Richter, 1935) measures energy at the source; intensity (Modified Mercalli, I to XII) measures effects at a place. One magnitude unit means 10 times the amplitude and about 32 times the energy.','One earthquake has one magnitude but many intensities. Lines joining places of equal intensity are isoseismals.',null,true,3,1,116) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f078','geological-assistant','geological-assistant-m1','Seismicity and plate movements','Fault type follows boundary type: shallow normal-fault earthquakes at ridges, strike-slip at transform faults, and thrust earthquakes (shallow to deep) at subduction zones.','Plates pull apart at ridges, slide past at transforms and push together at trenches. First-motion studies by Sykes (1967) confirmed this.',null,true,3,1,117) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f079','geological-assistant','geological-assistant-m1','Seismicity and plate movements','On an oceanic transform fault, earthquakes occur only on the segment between the two offset ridge crests; the fracture zone beyond is seismically quiet.','Only between the ridge crests do the two sides move in opposite directions. Beyond, both sides belong to the same plate and move together.',null,true,2,2,118) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f080','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','India broke away from Gondwanaland in steps: from Antarctica-Australia about 130 Ma, from Madagascar about 88 Ma, and from the Seychelles about 65 Ma.','The 88 Ma event left the columnar rhyolites of St. Mary''s Islands (Karnataka coast). The 65 Ma event goes with the Deccan Traps.',null,true,2,2,119) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f081','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','India drifted north very fast, about 15-20 cm/year, and began colliding with Eurasia about 50 million years ago (Eocene); it still converges at about 5 cm/year.','The collision closed the Tethys Sea and slowed India down. The continuing push keeps raising the Himalaya and causes its earthquakes.',null,true,3,1,120) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f082','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','The Deccan Traps erupted about 66 million years ago, at the Cretaceous-Palaeogene boundary, when India passed over the Reunion hotspot.','The plume head gave a huge burst of flood basalt (tholeiite). The hotspot today lies under Reunion Island in the Indian Ocean.',null,true,3,1,121) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f083','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','The Chagos-Laccadive Ridge (with Lakshadweep) is the track of the Reunion hotspot; the Ninetyeast Ridge and the Rajmahal Traps are linked to the Kerguelen hotspot.','As India moved north, each fixed hotspot drew a line of volcanoes on the moving plate. West side = Reunion, east side = Kerguelen.','UPSC Combined Geo-Scientist Mains 2020 (Geology Paper II)',true,3,1,122) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f084','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','The Indus-Tsangpo Suture Zone (ITSZ) marks the line where the Indian plate joined the Eurasian plate; it contains ophiolites, remnants of the Tethys ocean floor.','A suture is the scar where an ocean closed. It runs along the Indus and Tsangpo (upper Brahmaputra) river valleys.','UPSC Combined Geo-Scientist Prelims 2021 (Geology Paper II)',true,3,1,123) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f085','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','Himalayan thrusts from south to north: Himalayan Frontal Thrust (Siwalik over plains), Main Boundary Thrust (Lesser Himalaya over Siwalik) and Main Central Thrust (Greater Himalaya over Lesser Himalaya).','Thrusts get younger southwards as deformation moves towards the plains. Hook from the plains upward: F-B-C (Frontal, Boundary, Central).',null,true,3,1,124) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f086','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','Indian plate boundaries: Himalayan collision zone in the north, Andaman-Sunda subduction zone in the east, Chaman transform fault in the west, and Carlsberg-Central Indian Ridge in the south-west.','All three boundary types surround India: convergent (north, east), transform (west, a left-lateral fault in Pakistan-Afghanistan) and divergent (ocean ridge).',null,true,3,1,125) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f087','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','As of March 2026, India''s seismic code in force is IS 1893 (Part 1): 2016, with four zones: II (low), III, IV and V (highest). Zone I was merged into Zone II in 2002.','A 2025 revision added a new Zone VI for the Himalayan arc, but BIS withdrew it on 3 March 2026 and restored the 2016 map. Recheck before the exam.',null,true,3,1,126) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f088','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','Zone V (IS 1893: 2016) covers north-east India, parts of Jammu and Kashmir, Himachal Pradesh, Uttarakhand and north Bihar, the Rann of Kutch and the Andaman and Nicobar Islands. Kerala is in Zone III.','Zone V follows the plate boundary (Himalaya, Andaman arc) plus the active Kutch rift. Kerala is on the stable shield, so its hazard is moderate.',null,true,3,1,127) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f089','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','1897 Shillong earthquake (M 8.7 in older texts, revised Mw about 8.1) was studied by R.D. Oldham; the 1950 Assam-Tibet earthquake (Mw 8.6) is the largest instrumentally recorded on land.','Both struck the north-east, where the plate bends around the eastern Himalayan corner. The 1950 shock came on 15 August, Independence Day.',null,false,3,1,128) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f090','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','The 1967 Koyna earthquake in Maharashtra is the classic case of reservoir-induced seismicity.','Water filled behind the Koyna dam added load and seeped into faults, making them slip. Shocks began only after the reservoir was filled.',null,true,3,1,129) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f091','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','The Bhuj earthquake of 26 January 2001 (Mw 7.7) occurred in the Kutch rift of Gujarat, an intraplate region placed in Zone V.','Kutch is an old rift now being squeezed by the northward push of India. It is far from the plate boundary but very active.',null,true,3,1,130) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f092','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','The 1819 Kutch earthquake raised a long low ridge called the Allah Bund (''dam of God'') across the Rann of Kutch.','The fault lifted the ground and blocked a branch of the Indus river like a dam. It is a famous example of land uplift by an earthquake.',null,true,2,2,131) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f093','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','The Sumatra-Andaman earthquake of 26 December 2004 (Mw 9.1-9.3) was a megathrust event where the Indian plate subducts beneath the Burma plate; it caused the Indian Ocean tsunami.','About 1,300 km of the plate contact slipped and lifted the sea floor. The tsunami hit the Andaman-Nicobar Islands, Tamil Nadu and the Kerala coast.',null,true,3,1,132) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f094','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','The Western Ghats are interpreted as the uplifted edge (great escarpment) of a rifted passive margin, formed after India separated from Madagascar and the Seychelles.','When a continent rifts, its edge is lifted and then worn back as a steep west-facing scarp. So the Ghats are not fold mountains.',null,true,2,2,133) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f095','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','The strongest instrumentally recorded earthquake in Kerala is the Erattupetta (Kottayam-Idukki) earthquake of 12 December 2000, magnitude about 5.','Kerala has only mild intraplate shocks along old lineaments. This event is the usual example quoted for Kerala''s Zone III status.',null,false,1,3,134) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f096','geological-assistant','geological-assistant-m1','Earth and the solar system','The planetesimal hypothesis (Chamberlin and Moulton) and the tidal hypothesis (Jeans and Jeffreys) both needed a passing star to pull matter out of the Sun to make the planets.','These are ''catastrophic'' theories; the nebular theory is ''evolutionary''. They are rejected because such close star encounters are extremely rare.',null,true,2,2,135) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f097','geological-assistant','geological-assistant-m1','Earth and the solar system','The Earth is an oblate spheroid: the equatorial radius (about 6,378 km) is about 21 km longer than the polar radius (about 6,357 km); the mean radius is 6,371 km.','The Earth''s spin throws material outward at the equator, so it bulges there and is flattened at the poles.',null,true,3,1,136) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f098','geological-assistant','geological-assistant-m1','Earth and the solar system','The giant impact hypothesis says the Moon formed from debris thrown out when a Mars-sized body (Theia) struck the early Earth about 4.5 billion years ago.','It explains why Moon rocks are so like Earth''s mantle and why the Moon has only a very small iron core.',null,true,2,2,137) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f099','geological-assistant','geological-assistant-m1','Seafloor spreading and Plate Tectonics','Heat flow is highest at mid-ocean ridge crests and falls as the sea floor gets older; it is very low at trenches and high again over the volcanic arc and back-arc basin.','Hot mantle rises at ridges; a cold slab sinks at trenches and chills the area. Magma under the arc brings heat back up.',null,true,3,1,138) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f100','geological-assistant','geological-assistant-m1','Seafloor spreading and Plate Tectonics','Ocean depth increases with the age of the sea floor, roughly with the square root of age; ridge crests lie at about 2.5 km depth and old abyssal plains at 5 to 6 km.','As new lithosphere moves away from the ridge it cools, shrinks and gets denser, so it sits lower on the asthenosphere.',null,true,2,2,139) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f101','geological-assistant','geological-assistant-m1','Seafloor spreading and Plate Tectonics','The seven major plates are the Pacific, North American, South American, Eurasian, African, Indo-Australian and Antarctic; Nazca, Cocos, Philippine, Arabian, Caribbean, Scotia and Juan de Fuca are smaller plates.','Memory hook: the major plates carry the names of continents or of the Pacific Ocean. Any other name in a list is a minor plate.',null,true,2,2,140) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f102','geological-assistant','geological-assistant-m1','Seafloor spreading and Plate Tectonics','Trench (slab) rollback is the retreat of the trench and slab hinge towards the ocean side as the slab sinks steeply; it stretches the overriding plate and opens back-arc basins.','An old, heavy slab sinks faster than the plates converge, so the bend (hinge) moves backwards. The upper plate is pulled along and thins.','UPSC Combined Geo-Scientist Prelims 2021 (Geology Paper II)',true,2,2,141) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f104','geological-assistant','geological-assistant-m1','Island arcs, Oceanic islands and volcanic arcs','A volcanic arc forms above the place where the subducting slab reaches about 100 to 150 km depth; water driven out of the slab lowers the melting point of the mantle wedge above it.','This is ''flux melting'': water acts like salt on ice. The slab itself mostly does not melt; the hot mantle above it does.',null,true,3,1,142) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f105','geological-assistant','geological-assistant-m1','Island arcs, Oceanic islands and volcanic arcs','Iceland is an oceanic island sitting on the Mid-Atlantic Ridge above a hotspot, so the spreading ridge is exposed on land there; Yellowstone is a hotspot beneath a continent.','Ridge plus plume together make far more lava than a normal ridge, enough to build the island above sea level.',null,true,2,2,143) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f106','geological-assistant','geological-assistant-m1','Isostasy, orogeny and epeirogeny','Isostasy grew out of Everest''s survey of India: between Kalianpur and Kaliana the measured plumb-line deflection (5.24 seconds of arc) was only one-third of the 15.89 seconds Pratt calculated for the Himalaya''s pull.','The mountains attracted the plumb-bob less than their visible mass should. So there must be a mass deficit (light material) beneath them.',null,true,3,1,144) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f107','geological-assistant','geological-assistant-m1','Isostasy, orogeny and epeirogeny','In Airy isostasy, root thickness = height x crust density / (mantle density - crust density); with densities 2.7 and 3.3 g/cm3 the root is 4.5 times the height of the mountain.','The extra weight of the mountain must equal the weight ''saved'' by light root replacing heavy mantle. 2.7 / 0.6 = 4.5.',null,true,2,2,145) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f108','geological-assistant','geological-assistant-m1','Isostasy, orogeny and epeirogeny','Heiskanen''s isostasy model combines the Airy and Pratt ideas; Vening Meinesz''s regional model says a strong elastic lithosphere bends and spreads a load over a wide area.','Airy and Pratt assume each block floats on its own (local compensation). Real lithosphere is stiff, so it flexes like a plank under a weight.',null,true,2,2,146) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f109','geological-assistant','geological-assistant-m1','Isostasy, orogeny and epeirogeny','In Kober''s geosynclinal theory the rigid forelands are ''kratogen'', the mountain belt is ''orogen'', and a plateau caught between two marginal ranges is a ''Zwischengebirge'' (median mass), such as the Tibetan Plateau.','Kober pictured two rigid blocks squeezing a sediment-filled trough between them. The squeezed edges rise as ranges; the middle may stay as a high plateau.',null,true,2,2,147) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f110','geological-assistant','geological-assistant-m1','Seismic belts of the earth','An earthquake epicentre is located from the S-P arrival time gap at a minimum of three seismograph stations; a longer gap means a more distant earthquake.','Each station gives only a distance, which is a circle on the map. Three circles cross at one point.',null,true,3,1,148) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f111','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','Himalayan zones from south to north: Sub-Himalaya (Siwalik), Lesser Himalaya, Greater Himalaya, Tethys Himalaya, then the Indus-Tsangpo suture. The South Tibetan Detachment, a normal fault, separates the Greater and Tethys Himalaya.','Each zone is a slice of the old Indian margin stacked by thrusts. The detachment on top let the deep Greater Himalayan rocks squeeze out southward.',null,true,3,1,149) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f112','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','The Himalayan arc ends in two sharp hairpin bends called syntaxes: the western syntaxis at Nanga Parbat and the eastern syntaxis at Namcha Barwa.','The two corners of the Indian plate dig into Asia like the corners of a wedge, and the mountain ranges wrap around them.',null,true,3,1,150) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f113','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','The 1905 Kangra and 1934 Bihar-Nepal earthquakes were great Himalayan thrust events; the unbroken stretch between their rupture zones is called the central seismic gap.','A seismic gap is a part of an active fault that has not slipped for a long time. Strain keeps building there, so a great earthquake is expected.',null,true,3,1,151) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f114','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','The Main Himalayan Thrust is the gently north-dipping plate-contact fault (decollement) into which the Frontal, Boundary and Central thrusts merge at depth; it ruptured in the 2015 Gorkha (Nepal) earthquake, Mw 7.8.','India slides under the Himalaya along this one basal fault. The thrusts seen at the surface are branches (splays) rising from it.',null,true,2,2,152) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f115','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','The Indian and Australian plates are separated by a wide, diffuse zone of deformation in the equatorial Indian Ocean; the Mw 8.6 strike-slip earthquake of April 2012 off Sumatra occurred within it.','India is slowed by the Himalayan collision while Australia still moves freely into the Sunda trench, so the old single plate is breaking in between.',null,true,2,2,153) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f116','geological-assistant','geological-assistant-m1','Major tectonic features of the Oceanic and Continental crust','The Indian Ocean ridges form an inverted Y: the Central Indian Ridge, the Southwest Indian Ridge and the Southeast Indian Ridge meet at the Rodrigues Triple Junction.','Three plates (African, Indo-Australian, Antarctic) meet there, so three spreading ridges must join at one point.',null,true,2,2,154) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f117','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','In IS 1893 (Part 1): 2016, Zone II matches MSK intensity VI or less, Zone III VII, Zone IV VIII and Zone V IX or more; the zone factors are 0.10, 0.16, 0.24 and 0.36.','MSK is an intensity (shaking effect) scale. The zone factor is the expected peak ground shaking as a fraction of gravity, used in building design.',null,true,2,2,155) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f118','geological-assistant','geological-assistant-m1','Geodynamics of the Indian plate','Under the 2002/2016 BIS zoning map, about 59% of India''s land is in Zones III to V: roughly 11% in Zone V, 18% in Zone IV and 30% in Zone III; the remaining 41% is Zone II.','Hook: nearly three-fifths of India can get moderate to severe shaking. The highest zone is the smallest in area.',null,true,2,2,156) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1a-f120','geological-assistant','geological-assistant-m1','Gravity and magnetic anomalies at Mid-ocean ridges, deep sea trenches, continental shield areas and mountain chains','Old, stable continental shields are close to isostatic balance, so their isostatic and free-air gravity anomalies are small (near zero), unlike trenches and young mountain belts.','Shields have been worn flat and left undisturbed for a very long time, so they have had time to settle into floating balance.',null,true,2,2,157) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f001','geological-assistant','geological-assistant-m1','Weathering and soils','In Goldich''s weathering series, olivine weathers fastest and quartz is the most resistant among the common rock-forming minerals.','It follows the same order as Bowen''s reaction series. Minerals that crystallise first, at the highest temperature, are the least stable at the cool, wet surface.','UPSC Assistant Hydrogeologist (CGWB) 2019',true,3,1,158) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f002','geological-assistant','geological-assistant-m1','Weathering and soils','Exfoliation is the peeling of rock in curved sheets, caused mainly by pressure release (unloading) when the overlying rock is eroded away.','Granite formed at depth expands when its load is removed and cracks parallel to the surface. This gives rounded exfoliation domes.',null,true,3,1,159) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f003','geological-assistant','geological-assistant-m1','Weathering and soils','Frost wedging breaks rock because water expands by about 9% in volume when it freezes inside cracks.','It works best where temperature crosses 0 degrees C again and again, as in high mountains. It makes the angular scree (loose rock debris) below cliffs.',null,true,3,1,160) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f004','geological-assistant','geological-assistant-m1','Weathering and soils','Hydrolysis is the main chemical weathering process of silicate minerals; it changes feldspar into clay minerals such as kaolinite.','Hydrogen ions in slightly acid water replace the K, Na and Ca of feldspar. The leftover aluminium-silicon part becomes clay.',null,true,3,1,161) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f005','geological-assistant','geological-assistant-m1','Weathering and soils','The clay formed depends on leaching: smectite (montmorillonite) with poor drainage, kaolinite with good drainage, and gibbsite (bauxite) with extreme leaching.','More water passing through removes more silica and bases. What stays behind becomes richer in alumina step by step.',null,true,2,2,162) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f006','geological-assistant','geological-assistant-m1','Weathering and soils','A full soil profile from top to bottom is: O (organic litter), A (topsoil), E (leached layer), B (subsoil of accumulation), C (weathered parent material), R (bedrock).','Each horizon (layer) records a different job: adding humus, losing material, gaining material, and slowly breaking the rock.',null,true,3,1,163) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f007','geological-assistant','geological-assistant-m1','Weathering and soils','Eluviation is the washing out of clay, iron and humus from the A and E horizons; illuviation is their deposition in the B horizon.','Hook: E for Exit (eluviation), I for In (illuviation). So the B horizon is the zone of accumulation.',null,true,3,1,164) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f008','geological-assistant','geological-assistant-m1','Weathering and soils','The five soil-forming factors (Jenny, 1941) are climate, organisms, relief, parent material and time; climate is usually the most important.','Hook: CLORPT. Given enough time, the same climate makes similar soils even on different rocks.','Kerala PSC HSST Geology 2026',true,3,1,165) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f009','geological-assistant','geological-assistant-m1','Weathering and soils','Laterite is a residual product of intense tropical weathering: silica and bases are leached out, and iron and aluminium oxides are left behind.','It needs heat, heavy rain, good drainage and alternating wet and dry seasons. That is why it caps the midlands of Kerala.','Kerala PSC HSST Geology 2026',true,3,1,166) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f010','geological-assistant','geological-assistant-m1','Weathering and soils','Francis Buchanan named laterite in 1807 from Angadipuram in Malappuram district, Kerala; the name comes from the Latin ''later'', meaning brick.','The soft rock is cut into blocks that harden in air and are used as bricks. GSI keeps a National Geological Monument at Angadipuram.',null,true,3,1,167) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f011','geological-assistant','geological-assistant-m1','Weathering and soils','Black cotton soil (regur) forms mainly on Deccan basalt and is rich in montmorillonite clay, so it swells when wet and cracks deeply when dry.','Montmorillonite takes water between its layers and expands. This ''self-ploughing'' soil holds moisture well but damages buildings.','UPSC Assistant Hydrogeologist (CGWB) 2019',true,3,1,168) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f012','geological-assistant','geological-assistant-m1','Weathering and soils','In the Indo-Gangetic plain, khadar is the newer alluvium of the present flood plains; bhangar is the older alluvium on higher ground, with kankar nodules.','Khadar is renewed by floods every year, so it is more fertile. Kankar means lime (calcium carbonate) lumps.',null,true,3,1,169) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f013','geological-assistant','geological-assistant-m1','Weathering and soils','Alluvial soil is the most widespread soil group in India, while laterite soil is the most widespread soil in Kerala.','The great northern plains and deltas are all river-laid alluvium. Kerala''s hot, wet climate turns most midland rock into laterite.',null,true,2,2,170) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f014','geological-assistant','geological-assistant-m1','Mass wasting','Mass wasting is the downslope movement of rock and soil under gravity alone, without a transporting agent such as a river, wind or glacier.','Water only adds weight and cuts friction; it does not carry the material. That is the difference from erosion.',null,true,3,1,171) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f015','geological-assistant','geological-assistant-m1','Mass wasting','Varnes (1978) classified slope movements by type of movement (fall, topple, slide, spread, flow) and type of material (rock, debris, earth).','Names are made by joining the two parts: rock fall, debris flow, earth slide.',null,true,3,1,172) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f016','geological-assistant','geological-assistant-m1','Mass wasting','Creep is the slowest mass movement; its signs are tilted poles and fences, curved tree trunks and down-bent ends of strata.','The soil moves a few millimetres a year, too slow to see. Only its long-term effects on fixed objects show it.',null,true,3,1,173) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f017','geological-assistant','geological-assistant-m1','Mass wasting','Solifluction is the slow downslope flow of water-soaked soil over frozen ground, typical of periglacial (cold, near-glacier) regions.','In summer only the top layer thaws. Water cannot drain into the frozen layer below, so the soggy top layer slides.',null,true,3,1,174) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f018','geological-assistant','geological-assistant-m1','Mass wasting','A slump is a rotational slide on a curved, concave-up surface; the slipped block tilts backward and leaves a curved scarp at its head.','Compare: a translational slide moves on a flat plane such as a bedding or joint surface, with no back-tilting.',null,true,3,1,175) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f019','geological-assistant','geological-assistant-m1','Mass wasting','Heavy rain triggers landslides mainly by raising pore-water pressure, which lowers the effective stress and shear strength of the slope material.','Kerala''s monsoon debris flows (''urul pottal'') in the Western Ghats work this way, e.g. Pettimudi 2020 and Mundakkai-Chooralmala (Wayanad) 2024.',null,true,3,1,176) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f020','geological-assistant','geological-assistant-m1','Influence of climate on processes','Chemical weathering dominates in hot, humid climates; physical weathering dominates in cold climates and in deserts.','Chemical reactions need water and speed up with heat. Where water is frozen or missing, only mechanical breaking is left.',null,true,3,1,177) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f021','geological-assistant','geological-assistant-m1','Influence of climate on processes','Peltier (1950) defined nine morphogenetic regions, each with its own typical landform processes, using mean annual temperature and mean annual rainfall.','The nine are glacial, periglacial, boreal, maritime, selva, moderate, savanna, semi-arid and arid. Idea: climate decides which process is boss.',null,true,2,2,178) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f022','geological-assistant','geological-assistant-m1','Influence of climate on processes','Limestone is a weak, valley-forming rock in humid climates but a strong, cliff-forming rock in arid climates.','Limestone fails mainly by solution, which needs water. With little rain it resists better than most other rocks.',null,true,2,2,179) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f023','geological-assistant','geological-assistant-m1','Concept of erosion cycles','W. M. Davis (1899) said a landscape is a function of structure, process and stage (time); this is the ''geographical cycle'' or normal cycle of erosion.','Hook: SPS = Structure, Process, Stage. ''Normal'' means erosion by running water in a humid temperate climate.',null,true,3,1,180) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f024','geological-assistant','geological-assistant-m1','Concept of erosion cycles','Davis''s cycle begins with rapid uplift, then a long still-stand, and passes through youth, maturity and old age to end in a peneplain.','Peneplain = ''almost a plain''. Residual hills left on it are monadnocks. Relief is greatest in maturity; youth has V-valleys and waterfalls.',null,true,3,1,181) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f025','geological-assistant','geological-assistant-m1','Concept of erosion cycles','Walther Penck (1924) held that uplift and erosion act together, and that landform shape depends on the ratio of the rate of uplift to the rate of degradation.','Speeding uplift gives convex (waxing) slopes; slowing uplift gives concave (waning) slopes. His final low surface is the ''endrumpf''.',null,true,3,1,182) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f026','geological-assistant','geological-assistant-m1','Concept of erosion cycles','L. C. King''s pediplanation cycle explains landscapes by parallel retreat of scarps: pediments grow and join into a pediplain dotted with inselbergs.','Slopes move back while keeping their angle, instead of wearing down as in Davis''s model. King based it on semi-arid southern Africa.',null,true,3,1,183) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f027','geological-assistant','geological-assistant-m1','Concept of erosion cycles','Base level (J. W. Powell, 1875) is the lowest level to which a river can erode; sea level is the ultimate base level.','Lakes and hard rock bands act as local or temporary base levels for the stretch of river above them.',null,true,3,1,184) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f028','geological-assistant','geological-assistant-m1','Concept of erosion cycles','Rejuvenation (by uplift or a fall in base level) produces knickpoints, incised meanders, paired river terraces and valley-in-valley forms.','The river gets new energy and cuts down again into its old valley floor. The old floor is left as terraces on both sides.',null,true,3,1,185) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f029','geological-assistant','geological-assistant-m1','Concept of erosion cycles','Hack''s dynamic equilibrium concept (1960) says landforms keep a steady shape when erosional processes and rock resistance are in balance, whatever the stage.','It is a time-independent idea, unlike Davis''s stages. Every slope is adjusted to the rock under it and the work done on it.','Kerala PSC HSST Geology 2026',true,2,2,186) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f030','geological-assistant','geological-assistant-m1','Geomorphology of fluvial tracts','Stream competence is the largest particle size a stream can move; stream capacity is the total load it can carry.','Competence depends mainly on velocity, capacity mainly on discharge. Load moves in solution, in suspension and as bed load (rolling and hopping).',null,true,3,1,187) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f031','geological-assistant','geological-assistant-m1','Geomorphology of fluvial tracts','In a meander, erosion on the outer (concave) bank makes a cut bank, and deposition on the inner (convex) bank makes a point bar.','The fastest flow swings to the outside of the bend. The slow water on the inside drops its sand.','GATE Geology and Geophysics 2012',true,3,1,188) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f032','geological-assistant','geological-assistant-m1','Geomorphology of fluvial tracts','An oxbow lake forms when a river cuts through the narrow neck of a meander loop and abandons the loop.','The straight path is shorter and steeper, so the river takes it. The old loop is sealed off by silt.','GATE Geology and Geophysics 2024',true,3,1,189) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f033','geological-assistant','geological-assistant-m1','Geomorphology of fluvial tracts','Natural levees are low ridges along river banks built during overbank floods; the coarsest sediment drops nearest the channel, with backswamps beyond.','Flood water slows suddenly as it leaves the channel, so it drops sand and silt at once. Only clay reaches the backswamp.','UPSC Assistant Hydrogeologist (CGWB) 2019',true,3,1,190) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f034','geological-assistant','geological-assistant-m1','Geomorphology of fluvial tracts','Braided channels form where bed load is high, discharge is highly variable, the slope is steep and the banks are easily eroded.','The river cannot carry all its coarse load, so it drops bars and splits around them. Common below glaciers and mountain fronts.','Kerala PSC HSST Geology 2026',true,3,1,191) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f035','geological-assistant','geological-assistant-m1','Geomorphology of fluvial tracts','An alluvial fan forms where a stream leaves a mountain front and suddenly loses slope and confinement; merged fans form a bajada or piedmont plain.','The stream spreads out, slows and drops its load in a cone. The bhabar belt at the Himalayan foot is made of such merged fans.',null,true,3,1,192) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f036','geological-assistant','geological-assistant-m1','Geomorphology of fluvial tracts','Common delta shapes are arcuate (Nile, Ganga-Brahmaputra), bird-foot (Mississippi) and cuspate (Tiber); delta beds are named topset, foreset and bottomset.','Waves and currents smooth a delta into an arc. Where the river is stronger than the sea, long finger-like channels build a bird-foot.',null,true,3,1,193) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f037','geological-assistant','geological-assistant-m1','Geomorphology of fluvial tracts','Kerala has 44 rivers: 41 flow west and 3 (Kabani, Bhavani and Pambar) flow east to join the Cauvery system.','The Western Ghats crest lies close to the coast, so most rivers are short, steep and monsoon-fed. Do not confuse Pambar (east) with Pamba (west).',null,true,3,1,194) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f038','geological-assistant','geological-assistant-m1','Geomorphology of fluvial tracts','Periyar (244 km) is Kerala''s longest river, followed by Bharathapuzha (209 km) and Pamba (176 km).','Bharathapuzha drains through the Palghat Gap. Pamba, with other rivers, built the Kuttanad delta in Vembanad lake.',null,true,3,1,195) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f039','geological-assistant','geological-assistant-m1','Geomorphology of fluvial tracts','Kerala has three physiographic belts parallel to the coast: lowland (below 7.5 m), midland (7.5 to 75 m) and highland (above 75 m).','Lowland is coastal sand and backwaters, midland is laterite hills and valleys, highland is the Western Ghats.',null,true,3,1,196) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f040','geological-assistant','geological-assistant-m1','Geomorphology of fluvial tracts','Anamudi (2695 m) in Kerala is the highest peak in India south of the Himalaya; the Palghat Gap is the main break in the Western Ghats.','Anamudi is in Eravikulam, Idukki district. The Palghat Gap is a low pass about 30 km wide linking Kerala and Tamil Nadu.',null,true,3,1,197) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f041','geological-assistant','geological-assistant-m1','Geomorphology of arid zones','Wind erodes by deflation (lifting loose particles) and abrasion (sand-blasting); deflation leaves blow-outs and a lag of pebbles called desert pavement.','Wind can lift only sand, silt and dust. The stones it cannot move stay behind and armour the surface.',null,true,3,1,198) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f042','geological-assistant','geological-assistant-m1','Geomorphology of arid zones','Ventifacts are stones faceted and polished by wind-blown sand; a three-faced ventifact is called a dreikanter.','Sand-blast cuts a flat face on the windward side. When the stone turns or the wind shifts, a new face is cut.','GATE Geology and Geophysics 2024',true,3,1,199) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f043','geological-assistant','geological-assistant-m1','Geomorphology of arid zones','Yardangs are streamlined ridges cut parallel to the prevailing wind; zeugen are flat-topped masses with a hard cap rock over soft horizontal layers.','Both are made by wind abrasion on rocks of unequal hardness. Mushroom rocks are undercut because most sand travels near the ground.',null,true,3,1,200) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f044','geological-assistant','geological-assistant-m1','Geomorphology of arid zones','A barchan is a crescent-shaped dune whose horns point downwind; it forms with limited sand supply and wind from one steady direction.','The thin edges move faster than the thick middle, so they run ahead as horns. The steep slip face is on the lee (sheltered) side.',null,true,3,1,201) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f045','geological-assistant','geological-assistant-m1','Geomorphology of arid zones','Seif (longitudinal) dunes run parallel to the wind, transverse dunes lie across it, and parabolic dunes have horns pointing upwind, held by vegetation.','A parabolic dune is a barchan turned backward: plants pin the arms while the bare middle blows forward.',null,true,3,1,202) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f046','geological-assistant','geological-assistant-m1','Geomorphology of arid zones','Loess is unstratified wind-blown silt that can stand in vertical walls; the thickest deposits are in the Loess Plateau of north China.','The dust comes from deserts and glacial outwash plains. Angular grains and a little lime cement let it stand in cliffs.',null,true,3,1,203) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f047','geological-assistant','geological-assistant-m1','Geomorphology of arid zones','A pediment is a gently sloping erosional rock surface at the foot of a desert mountain; the bajada beyond it is depositional, and the playa is the flat basin floor.','Order from mountain to basin centre: pediment, bajada, playa. A playa holds a temporary salt lake after rain.',null,true,3,1,204) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f048','geological-assistant','geological-assistant-m1','Geomorphology of arid zones','An inselberg is an isolated, steep-sided residual hill rising abruptly from a plain; a dome-shaped one is called a bornhardt.','Inselberg means ''island mountain''. It is the last remnant left when scarps retreat across massive, poorly jointed rock.',null,true,3,1,205) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f049','geological-assistant','geological-assistant-m1','Geomorphology of coastal regions','Wave erosion makes a notch, then a sea cliff and a wave-cut platform; on headlands the sequence is cave, arch, stack and stump.','Waves attack weak joints from both sides of a headland. Caves meet to form an arch, and the roof falls to leave a stack.',null,true,3,1,206) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f050','geological-assistant','geological-assistant-m1','Geomorphology of coastal regions','Longshore drift moves sediment along the shore in a zig-zag, because swash runs up the beach obliquely while backwash returns straight down the slope.','It happens when waves reach the shore at an angle. Groynes are built to trap this moving sand.',null,true,3,1,207) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f051','geological-assistant','geological-assistant-m1','Geomorphology of coastal regions','A spit is a sand ridge joined to land at one end; a tombolo joins an island to the mainland; a barrier bar or island encloses a lagoon.','All three are built by longshore drift. Hook: tombolo ''ties'' the island.',null,true,3,1,208) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f052','geological-assistant','geological-assistant-m1','Geomorphology of coastal regions','D. W. Johnson (1919) classified shorelines as submergence, emergence, neutral and compound; rias and fjords are submergence features.','Ria = drowned river valley, fjord = drowned glacial trough. Raised beaches and marine terraces show emergence.',null,true,3,1,209) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f053','geological-assistant','geological-assistant-m1','Geomorphology of coastal regions','Kerala''s coast is a barrier-lagoon coast: long sandy barrier beaches enclose backwaters (kayals), the largest being Vembanad.','Longshore drift built sand barriers across river mouths and trapped lagoons behind them. Kerala has 34 backwaters.','Kerala PSC HSST Geology 2026',true,3,1,210) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f054','geological-assistant','geological-assistant-m1','Geomorphology of coastal regions','Vembanad is Kerala''s largest backwater lake and Sasthamkotta its largest freshwater lake; both, with Ashtamudi, were declared Ramsar sites in 2002.','Ramsar site = wetland of international importance. Sasthamkotta (Kollam) has no river feeding it; it is fed by groundwater and rain.',null,true,3,1,211) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f055','geological-assistant','geological-assistant-m1','Geomorphology of coastal regions','Kuttanad, the delta and backwater region at the southern end of Vembanad lake, has rice fields lying below mean sea level and acidic peaty ''kari'' soils.','The fields are reclaimed lake bed kept dry by bunds (earth walls). It is the lowest-lying land in India.',null,true,3,1,212) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f056','geological-assistant','geological-assistant-m1','Geomorphology of coastal regions','Mudbanks (''chakara'') are calm near-shore patches of thick suspended mud that appear along the Kerala coast during the south-west monsoon.','The fluid mud damps the waves, so the sea stays calm and fish gather there. They are best known off the Alappuzha coast.',null,true,2,2,213) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f057','geological-assistant','geological-assistant-m1','Karst landscapes','Karst develops best in thick, dense, well-jointed soluble rock (limestone or dolomite) with good rainfall and enough relief for groundwater to circulate.','Rain with dissolved CO2 is a weak acid that dissolves calcite along joints. The name comes from the Karst (Kras) plateau of Slovenia.','GATE Geology and Geophysics 2024',true,3,1,214) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f058','geological-assistant','geological-assistant-m1','Karst landscapes','Lapies (karren) are grooved, fluted limestone surfaces; in a limestone pavement the blocks are called clints and the widened joints grikes.','They are small solution sculptures on bare rock, not closed hollows. So lapies are not a kind of sinkhole.','UPSC Assistant Hydrogeologist (CGWB) 2019',true,3,1,215) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f059','geological-assistant','geological-assistant-m1','Karst landscapes','Karst closed depressions in order of increasing size are sinkhole (doline), uvala (merged dolines) and polje (a large flat-floored basin).','Hook: D-U-P, small to big. A stream vanishing underground enters by a swallow hole (ponor).','UPSC Assistant Hydrogeologist (CGWB) 2019',true,3,1,216) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f060','geological-assistant','geological-assistant-m1','Karst landscapes','Stalactites hang from a cave roof, stalagmites grow up from the floor, and the two join to form a column (pillar).','Hook: stalaCtite = Ceiling, stalaGmite = Ground. Both are calcite left when dripping water loses CO2.',null,true,3,1,217) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f061','geological-assistant','geological-assistant-m1','Geomorphology of glaciated ranges','Glaciers erode by plucking (pulling out blocks) and abrasion (grinding); abrasion leaves striations that show the direction of ice flow, and makes rock flour.','Stones frozen in the ice base act like sandpaper. Rock flour is the fine powder that makes glacial streams milky.',null,true,3,1,218) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f062','geological-assistant','geological-assistant-m1','Geomorphology of glaciated ranges','A cirque is an armchair-shaped hollow at a glacier head; two cirques back to back leave an arete, and three or more leave a horn (pyramidal peak).','Cirque walls cut backward into the mountain from several sides. A lake left in an empty cirque is a tarn.',null,true,3,1,219) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f063','geological-assistant','geological-assistant-m1','Geomorphology of glaciated ranges','Valley glaciers carve U-shaped troughs with truncated spurs and hanging valleys; a glacial trough drowned by the sea is a fjord.','The big main glacier cuts deeper than its small tributaries. So tributary valleys are left ''hanging'' high on the trough wall, often with waterfalls.','GATE Geology and Geophysics 2024',true,3,1,220) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f064','geological-assistant','geological-assistant-m1','Geomorphology of glaciated ranges','A roche moutonnee is a bedrock knob with a smooth, gentle up-ice (stoss) side made by abrasion and a steep, rough down-ice (lee) side made by plucking.','Ice presses and grinds as it climbs the knob, then pulls blocks away as it leaves. It is an erosional form.',null,true,3,1,221) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f065','geological-assistant','geological-assistant-m1','Geomorphology of glaciated ranges','A drumlin is a streamlined hill of till with its steep blunt end facing up-ice and its gentle tail pointing down-ice; swarms give ''basket of eggs'' topography.','It is a depositional form, and its asymmetry is the opposite of a roche moutonnee. Both show the direction of ice flow.','UPSC Assistant Hydrogeologist (CGWB) 2019',true,3,1,222) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f066','geological-assistant','geological-assistant-m1','Geomorphology of glaciated ranges','Till is unsorted, unstratified debris dropped directly by ice; moraines made of it are lateral, medial, terminal (end), recessional and ground moraines.','Ice carries clay and boulders together and cannot sort them. A medial moraine forms where two lateral moraines join.',null,true,3,1,223) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f067','geological-assistant','geological-assistant-m1','Geomorphology of glaciated ranges','Eskers are long winding ridges of stratified sand and gravel laid by meltwater streams under the ice; kames are mounds; kettles are hollows left by melted buried ice blocks.','These are glacio-fluvial (meltwater) deposits, so they are sorted and layered, unlike till.',null,true,3,1,224) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f068','geological-assistant','geological-assistant-m1','Drainage basin analysis','Dendritic (tree-like) drainage develops on uniform rocks or flat-lying beds where there is no structural control.','With nothing to guide them, streams branch at random acute angles like the twigs of a tree. It is the most common pattern.',null,true,3,1,225) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f069','geological-assistant','geological-assistant-m1','Drainage basin analysis','Trellis drainage develops on folded or tilted beds of alternating hard and soft rock: long parallel main streams with short tributaries joining at right angles.','Main streams follow the soft beds along strike. Short streams run down the hard ridges to meet them.',null,true,3,1,226) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f070','geological-assistant','geological-assistant-m1','Drainage basin analysis','Rectangular drainage, with right-angled bends in main streams and tributaries alike, indicates control by joints or faults.','Water follows the fracture lines because broken rock erodes easily. Two fracture sets at right angles give the pattern.',null,true,3,1,227) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f071','geological-assistant','geological-assistant-m1','Drainage basin analysis','Radial drainage flows outward from a dome or volcano, centripetal drainage flows inward into a basin, and annular drainage forms rings around an eroded dome.','Annular (ring-like) streams follow the circular outcrops of soft beds exposed when a dome is worn down.',null,true,3,1,228) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f072','geological-assistant','geological-assistant-m1','Drainage basin analysis','A consequent stream follows the original slope; a subsequent stream follows weak rock belts along strike; an obsequent stream flows opposite to the consequent.','A resequent stream flows the same way as the consequent but at a lower, later level. An insequent stream shows no control (dendritic).',null,true,3,1,229) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f073','geological-assistant','geological-assistant-m1','Drainage basin analysis','An antecedent river is older than the uplift it cuts across (Indus, Sutlej, Brahmaputra); a superimposed river was let down from a younger cover onto older structures.','Antecedent = ''came before'' the mountains and kept its course by cutting gorges. Damodar, Subarnarekha and Chambal are usual superimposed examples.',null,true,3,1,230) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f074','geological-assistant','geological-assistant-m1','Drainage basin analysis','In Strahler''s stream ordering (1952), fingertip streams are first order; two streams of equal order u join to make order u+1; unequal orders keep the higher order.','It is a simplified form of Horton''s (1945) system. Example: 2+2 gives 3, but 3+2 stays 3.',null,true,3,1,231) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f075','geological-assistant','geological-assistant-m1','Drainage basin analysis','Bifurcation ratio is the number of streams of one order divided by the number of the next higher order; it is usually 3 to 5 where structure does not control drainage.','Higher values point to strong structural control (folds, faults) or a long narrow basin.','Kerala PSC HSST Geology 2026',true,3,1,232) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f076','geological-assistant','geological-assistant-m1','Drainage basin analysis','Horton''s law of stream numbers: the number of streams falls with rising order in an inverse geometric series; mean stream length rises in a direct geometric series.','So a plot of log (number of streams) against order is a straight line sloping down. Its slope gives the bifurcation ratio.',null,true,3,1,233) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f077','geological-assistant','geological-assistant-m1','Drainage basin analysis','Drainage density is total stream length divided by basin area (km per sq km); it is high on impermeable rocks, steep slopes and sparsely vegetated land.','Where water cannot soak in, more of it runs off and cuts more channels. Low density means permeable ground and good recharge.','GATE Geology and Geophysics 2024',true,3,1,234) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f078','geological-assistant','geological-assistant-m1','Drainage basin analysis','Horton''s form factor is basin area divided by the square of basin length; a low value means an elongated basin with a flatter, longer-lasting flood peak.','In a long narrow basin, water from far and near parts reaches the outlet at different times. Related shape indices: circularity ratio (Miller), elongation ratio (Schumm).',null,true,2,2,235) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f079','geological-assistant','geological-assistant-m1','Drainage basin analysis','The hypsometric curve relates area to elevation; Strahler''s hypsometric integral is high for youthful, little-eroded basins and low for old, deeply eroded ones.','The integral is the share of the original rock mass still left. Above about 0.6 is youthful, below about 0.35 is the old (monadnock) stage.','UPSC Assistant Hydrogeologist (CGWB) 2019',true,2,2,236) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f080','geological-assistant','geological-assistant-m1','Applications of geomorphology','Placers concentrate heavy, hard, chemically stable minerals (gold, cassiterite, diamond, ilmenite, monazite) where current speed drops, such as the inside of meander bends and below confluences.','Heavy grains settle first when water slows, while light quartz is carried on. So landform study tells where to dig.',null,true,3,1,237) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f081','geological-assistant','geological-assistant-m1','Applications of geomorphology','The Chavara beach placer in Kollam district, Kerala, is rich in ilmenite, rutile, zircon, monazite and sillimanite.','Rivers bring heavy minerals from khondalite and charnockite rocks, and waves sort them on the beach. IREL and KMML mine them.',null,true,3,1,238) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f082','geological-assistant','geological-assistant-m1','Applications of geomorphology','In hard-rock terrain, valley fills, buried pediments, palaeochannels and fracture-controlled straight valleys are good groundwater zones; inselbergs and residual hills are poor.','Thick loose or weathered material stores water, and fractures let it move. Bare rock hills only shed water as run-off.',null,true,3,1,239) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f083','geological-assistant','geological-assistant-m1','Applications of geomorphology','Dam sites favour a narrow valley with sound, watertight rock; karst terrain is risky because solution cavities leak water and may collapse.','Old landslide scars and buried channels found by landform study are also avoided in dam, tunnel and road alignment.',null,true,2,2,240) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f084','geological-assistant','geological-assistant-m1','Applications of geomorphology','Geomorphic mapping supports flood-plain zoning, landslide hazard zonation and coastal erosion studies, because landforms record where these processes acted before.','Levees, backswamps and old channels mark flood-prone land. Old scars and debris fans mark slopes that can fail again.',null,true,2,2,241) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f085','geological-assistant','geological-assistant-m1','Topographical maps','The Survey of India, founded in 1767 and headquartered at Dehradun, is India''s national mapping agency and publishes the topographical sheets (toposheets).','It is the oldest scientific department of the Government of India and works under the Department of Science and Technology.',null,true,3,1,242) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f086','geological-assistant','geological-assistant-m1','Topographical maps','In the India and Adjacent Countries series, each numbered sheet (for example 58) covers 4 degrees by 4 degrees at a scale of 1:1,000,000.','These ''million sheets'' are the base of the whole numbering system. Southern Kerala falls in sheet 58.',null,true,3,1,243) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f087','geological-assistant','geological-assistant-m1','Topographical maps','Each 4-degree sheet is divided into 16 degree sheets (1 degree by 1 degree), lettered A to P, at a scale of 1:250,000, for example 58 D.','4 x 4 = 16 squares. Letters run down each column, starting from the north-west corner.',null,true,3,1,244) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f088','geological-assistant','geological-assistant-m1','Topographical maps','Each degree sheet is divided into 16 sheets of 15 minutes by 15 minutes, numbered 1 to 16, at a scale of 1:50,000, for example 58 D/14.','Each of these is cut again into four 7.5-minute sheets at 1:25,000, named NW, NE, SW and SE (for example 58 D/14/NE).',null,true,3,1,245) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f089','geological-assistant','geological-assistant-m1','Topographical maps','Open Series Maps, brought in by the National Map Policy 2005, use the WGS-84 datum and UTM projection; older toposheets used the Everest datum and polyconic projection.','Open Series Maps are for civilian use; Defence Series Maps are restricted. The National Geospatial Policy 2022 (notified December 2022) replaced the 2005 policy.',null,true,2,2,246) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f090','geological-assistant','geological-assistant-m1','Topographical maps','On a 1:50,000 map 2 cm represents 1 km; on a 1:25,000 map 4 cm represents 1 km; on a 1:250,000 map 1 cm represents 2.5 km.','1:50,000 means 1 cm = 50,000 cm = 500 m. A map that shows more detail of a smaller area (1:25,000) is the ''larger scale'' map.',null,true,3,1,247) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f091','geological-assistant','geological-assistant-m1','Topographical maps','Closely spaced contours show a steep slope and widely spaced contours a gentle slope; contour V''s point upstream in valleys and downhill on spurs.','A contour joins points of equal height. Contours of different height cannot cross; they only merge at a vertical cliff.',null,true,3,1,248) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f092','geological-assistant','geological-assistant-m1','Topographical maps','On Survey of India toposheets contours are brown, water features blue, forests green, cultivated land yellow, and settlements and roads red.','Black is used for names, railways and boundaries. Hook: brown earth, blue water, green trees, yellow crops.',null,true,3,1,249) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f093','geological-assistant','geological-assistant-m1','Weathering and soils','Spheroidal weathering rounds joint-bounded blocks into concentric onion-like shells by chemical attack along joints; it is common in basalt, dolerite and granite.','Corners are attacked from three sides and edges from two, so they wear away fastest. It is chemical, unlike exfoliation, which is due to unloading.',null,true,3,1,250) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f094','geological-assistant','geological-assistant-m1','Weathering and soils','ICAR groups Indian soils into eight types: alluvial, black, red and yellow, laterite, arid (desert), saline, peaty (marshy) and forest (mountain) soils.','Alluvial soil covers the largest area. Black soil goes with Deccan basalt, red soil with old crystalline rocks, laterite with hot wet uplands.',null,true,2,2,251) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f095','geological-assistant','geological-assistant-m1','Weathering and soils','Red soil forms on old crystalline rocks (granite, gneiss) of Peninsular India; its colour comes from finely spread ferric iron oxide, and it looks yellow when hydrated.','It is poor in nitrogen, phosphorus and humus. It is common in Tamil Nadu, Karnataka, Andhra Pradesh, Odisha and Chhattisgarh.',null,true,3,1,252) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f096','geological-assistant','geological-assistant-m1','Mass wasting','The factor of safety of a slope is the resisting force (shear strength) divided by the driving force (shear stress); the slope fails when it falls below 1.','Heavy rain, cutting the toe of the slope, loading its top and earthquake shaking all push the ratio down.',null,true,3,1,253) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f097','geological-assistant','geological-assistant-m1','Mass wasting','The angle of repose is the steepest angle at which loose dry material stays stable; it is about 30 to 35 degrees for dry sand.','Coarser and more angular fragments can stand steeper. Scree (talus) slopes below cliffs rest at this angle.',null,true,2,2,254) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f098','geological-assistant','geological-assistant-m1','Influence of climate on processes','Humid regions typically have rounded, soil-covered slopes that are convex above and concave below; arid regions have angular, bare slopes with sharp breaks of slope.','In wet climates creep and chemical weathering smooth the land under a soil cover. In deserts weak weathering and rare flash floods leave bare rock and sharp edges.',null,true,2,2,255) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f099','geological-assistant','geological-assistant-m1','Influence of climate on processes','Most desert drainage is internal (endoreic): ephemeral streams flow only after rare storms and end in closed basins instead of reaching the sea.','Rain is too little and evaporation too high for rivers to last. The dry channels are called wadis or arroyos.',null,true,2,2,256) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f100','geological-assistant','geological-assistant-m1','Geomorphology of fluvial tracts','River capture (stream piracy) happens when a stream cutting headward diverts another; it leaves an elbow of capture, a wind gap and a misfit (underfit) stream.','The capturing stream has a steeper slope or weaker rock to cut. The beheaded stream is now too small for its old valley.',null,true,3,1,257) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f101','geological-assistant','geological-assistant-m1','Geomorphology of fluvial tracts','A graded stream has a smooth, concave-upward long profile with a slope just enough to carry its load (Mackin, 1948).','The profile is steep near the source and gentle near the mouth. On average such a river neither cuts down nor builds up its bed.',null,true,2,2,258) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f102','geological-assistant','geological-assistant-m1','Geomorphology of fluvial tracts','The Western Ghats (Sahyadri) run about 1600 km parallel to the west coast from the Tapi valley to Kanyakumari; they became a UNESCO World Heritage Site in 2012.','Their steep western face is a great escarpment. It blocks the monsoon winds, so the Kerala side is very wet and its rivers are short and steep.',null,true,3,1,259) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f103','geological-assistant','geological-assistant-m1','Geomorphology of fluvial tracts','The Palghat Gap lies between the Nilgiri Hills to the north and the Anamalai Hills to the south; the Bharathapuzha flows west through it.','It lets road, rail and dry winds pass between Kerala and Tamil Nadu. Farther south, the smaller Shencottah (Aryankavu) gap is the next break.',null,true,3,1,260) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f104','geological-assistant','geological-assistant-m1','Geomorphology of arid zones','An erg is a sandy desert (sand sea), a reg is a stony desert plain covered with gravel, and a hamada is a bare rock desert plateau.','Deflation (wind removal of fines) explains the last two: wind takes the sand away and leaves gravel or bare rock.',null,true,3,1,261) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f105','geological-assistant','geological-assistant-m1','Geomorphology of coastal regions','Darwin''s subsidence theory says that as a volcanic island slowly sinks, a fringing reef grows upward to become a barrier reef and finally an atoll.','Corals keep growing up toward sunlight as the island goes down. The Lakshadweep islands are atolls.',null,true,3,1,262) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f106','geological-assistant','geological-assistant-m1','Karst landscapes','Limestone dissolves by carbonation: rain water with dissolved carbon dioxide (weak carbonic acid) changes calcium carbonate into soluble calcium bicarbonate.','CaCO3 + H2O + CO2 gives Ca(HCO3)2. When the water loses CO2 inside a cave, the reaction reverses and calcite is deposited as dripstone.',null,true,3,1,263) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f107','geological-assistant','geological-assistant-m1','Karst landscapes','Terra rossa is the red, clay-rich residual soil left on limestone after the carbonate has dissolved away.','The insoluble impurities of limestone (clay and iron oxide) stay behind. The name means ''red earth''.',null,true,2,2,264) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f108','geological-assistant','geological-assistant-m1','Karst landscapes','Well-known karst caves of India include the Borra Caves (Andhra Pradesh), Kutumsar Cave (Chhattisgarh) and the long cave systems of Meghalaya.','All are in thick limestone belts with good rainfall. Kerala has very little limestone, so karst is not important there.',null,true,2,2,265) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f109','geological-assistant','geological-assistant-m1','Karst landscapes','Humid tropical karst shows cone (cockpit) karst and steep-sided tower karst, as in South China, instead of the doline plains of temperate karst.','Heavy rain and plant acids dissolve limestone fast. Only steep residual hills are left standing between the wide solution hollows.',null,true,1,3,266) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f110','geological-assistant','geological-assistant-m1','Geomorphology of glaciated ranges','Snow changes to granular firn (neve) and then to glacier ice by compaction and recrystallisation; the snow line is the lower limit of permanent snow.','Air is squeezed out as the snow is buried. A glacier gains mass above the snow line (accumulation zone) and loses it below (ablation zone).',null,true,2,2,267) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f111','geological-assistant','geological-assistant-m1','Drainage basin analysis','Parallel drainage develops on steep uniform slopes; deranged drainage with many lakes and swamps marks recently glaciated ground; barbed drainage suggests river capture or tilting.','In barbed drainage the tributaries join pointing upstream, like fish-hook barbs. This shows the main river once flowed the other way.',null,true,2,2,268) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f112','geological-assistant','geological-assistant-m1','Drainage basin analysis','Stream frequency is the number of stream segments per unit area; the constant of channel maintenance is the reciprocal of drainage density, and the length of overland flow is half of that.','Example: drainage density 2 km per sq km gives a constant of 0.5 sq km per km and an overland flow length of 0.25 km.',null,true,2,2,269) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f113','geological-assistant','geological-assistant-m1','Drainage basin analysis','Elongation ratio (Schumm) is the diameter of a circle with the same area as the basin divided by basin length; circularity ratio (Miller) is basin area divided by the area of a circle with the same perimeter.','Both are 1 for a perfectly circular basin and get smaller as the basin gets longer and narrower.',null,true,2,2,270) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f114','geological-assistant','geological-assistant-m1','Applications of geomorphology','Bauxite and laterite occur as flat cappings on plateau tops (old planation surfaces), so mapping such surfaces guides the search for residual deposits.','Residual ore needs long, deep weathering on stable flat ground. Examples: bauxite on the Eastern Ghats plateaus and the ''pat'' lands of Chotanagpur.',null,true,2,2,271) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f115','geological-assistant','geological-assistant-m1','Applications of geomorphology','A basin with high drainage density, steep slopes and a nearly circular shape gives quick run-off and a sharp, high flood peak.','Water from all parts reaches the outlet fast and at about the same time. So morphometry helps to judge flood risk in basins that have no gauges.',null,true,3,1,272) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f116','geological-assistant','geological-assistant-m1','Topographical maps','One 4-degree sheet contains 16 degree sheets and 16 x 16 = 256 sheets of 1:50,000 scale.','Each degree sheet (1:250,000) is cut into 16 sheets of 15 minutes. So 16 degree sheets x 16 = 256.',null,true,2,2,273) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f117','geological-assistant','geological-assistant-m1','Topographical maps','The standard contour interval on metric 1:50,000 Survey of India toposheets is 20 m.','Contour interval is the height difference between neighbouring contours. Every fifth contour (each 100 m) is drawn thicker as an index contour.',null,true,3,1,274) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f118','geological-assistant','geological-assistant-m1','Topographical maps','Closed contours with values rising inward show a hill; values falling inward show a depression; a saddle (col) is the low point on a ridge between two hills.','Evenly spaced contours mean a uniform slope. In a concave slope the contours are close together at the top and wide apart at the bottom.',null,true,3,1,275) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1b-f119','geological-assistant','geological-assistant-m1','Topographical maps','On a toposheet a bench mark (BM) is a permanent point of precisely levelled height, a spot height is a dot with its height printed beside it, and a small triangle marks a triangulation station.','These give exact heights between the contours. Heights are measured above mean sea level.',null,true,2,2,276) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f001','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Passive sensors record reflected sunlight or emitted heat; active sensors such as radar and LiDAR send out their own energy and record the return.','Active means the sensor carries its own ''torch''. So radar works at night, but an ordinary camera does not.',null,true,3,1,277) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f002','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Visible light spans about 0.4-0.7 µm: blue 0.4-0.5, green 0.5-0.6 and red 0.6-0.7 µm; near-infrared begins just beyond red at 0.7 µm.','Order of increasing wavelength: blue, green, red, then infrared. ''Infra-red'' simply means ''beyond red''.',null,true,3,1,278) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f003','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Atmospheric windows are wavelength bands where the atmosphere absorbs very little: mainly 0.3-1.3 µm, 1.5-1.8 µm, 2.0-2.4 µm, 3-5 µm, 8-14 µm and the microwave region.','Sensors are built only for these ''open windows''. Outside them, water vapour, carbon dioxide and ozone block the signal.',null,true,3,1,279) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f004','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Thermal infrared sensing of the Earth''s surface uses the 8-14 µm window; the 3-5 µm window suits very hot targets such as fires and lava.','The ground at normal temperature gives out most heat near 10 µm. Hotter things glow at shorter wavelengths.',null,true,3,1,280) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f005','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Wien''s displacement law: wavelength of peak emission (µm) = 2898 / T (kelvin), giving about 0.5 µm for the Sun and about 9.7 µm for the Earth at 300 K.','Hotter body, shorter peak wavelength. This is why sunlight peaks in the visible and Earth''s own glow is in thermal infrared.',null,true,2,2,281) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f006','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Rayleigh scattering by gas molecules varies as the inverse fourth power of wavelength, so short blue wavelengths are scattered far more than red.','This makes the sky blue and causes bluish haze on aerial photos. A yellow (minus-blue) haze filter cuts it.',null,true,3,1,282) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f007','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Healthy vegetation absorbs blue and red light (chlorophyll), reflects some green, and reflects very strongly in near-infrared because of the internal cell structure of leaves.','Low red plus high near-infrared is the ''fingerprint'' of green plants. Stressed plants lose the near-infrared peak.','GATE 2026 Geomatics Engineering (GE)',true,3,1,283) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f008','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Clear water absorbs almost all near-infrared and shortwave-infrared energy, so water bodies look black on infrared images.','This makes the land-water boundary very sharp in infrared bands, which is useful for mapping tanks, rivers and shorelines.',null,true,3,1,284) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f009','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Snow and cloud are both bright in visible bands, but in shortwave infrared near 1.6 µm snow turns dark while cloud stays bright.','Ice absorbs shortwave infrared strongly; tiny cloud droplets still scatter it. So a 1.6 µm band separates the two.','GATE 2026 Geomatics Engineering (GE)',true,2,2,285) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f010','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','A vertical aerial photo has the camera axis within about 3° of vertical; a low oblique does not show the horizon; a high oblique shows the horizon.','Memory hook: ''High oblique = Horizon''. Vertical photos are the ones used for mapping and stereo work.','GATE 2026 Geomatics Engineering (GE)',true,3,1,286) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f011','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','Scale of a vertical aerial photograph = f / (H - h), where f is focal length, H is flying height above datum and h is ground elevation.','Longer lens gives a larger scale; flying higher gives a smaller scale. Keep f and H in the same unit.','GATE 2026 Geomatics Engineering (GE)',true,3,1,287) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f012','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','Photo scale is not uniform over hilly ground: hilltops are closer to the camera and appear at a larger scale than valleys.','Scale depends on the camera-to-ground distance (H - h). So one photo can have many scales; only flat ground gives one scale.',null,true,2,2,288) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f013','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','An aerial photograph is a central (perspective) projection, whereas a map is an orthographic projection.','All rays pass through one point, the lens. So tall or high objects lean outward on a photo, but not on a map.',null,true,3,1,289) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f014','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','For stereoscopic cover, successive aerial photos overlap about 60% along the flight line (forward overlap) and about 20-30% between adjacent strips (side lap).','More than 50% forward overlap makes sure every ground point appears on at least two photos, which stereo viewing needs.',null,true,3,1,290) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f015','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','Relief displacement d = r x h / H, where r is radial distance of the image point from the photo centre, h is object height and H is flying height above the object''s base.','It grows with object height and distance from the centre, and shrinks when the aircraft flies higher.','GATE 2026 Geomatics Engineering (GE)',true,3,1,291) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f016','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','Relief displacement is radial from the nadir point: tops of elevated objects shift outward, depressions shift inward, and it is zero at the nadir.','An object directly below the camera is seen straight down, so it cannot lean. Objects near photo edges lean the most.',null,true,3,1,292) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f017','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','The principal point is where lines joining opposite fiducial marks cross; the nadir is the point vertically below the camera; the isocentre lies midway between them on a tilted photo.','On a truly vertical photo all three points coincide. Tilt displacement is radial from the isocentre.',null,true,2,2,293) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f018','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','Stereoscopic parallax is the apparent shift in an object''s position on two overlapping photos caused by the change in camera position; higher points show larger parallax.','Hold a finger close and blink each eye: a near object jumps more than a far one. Hilltops are ''nearer'' to the camera.',null,true,3,1,294) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f019','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','Object height from parallax: h = H x dP / (Pb + dP), where H is flying height, Pb is the absolute parallax at the base and dP is the parallax difference between top and base.','A bigger parallax difference means a taller object. Pb is roughly equal to the photo base (distance between photo centres).',null,true,2,2,295) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f020','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','Pocket (lens) and mirror stereoscopes are used to view stereo pairs in 3D; a parallax bar (stereometer) measures the parallax difference between two points.','A mirror stereoscope lets you see the whole overlap at once. The parallax bar turns the 3D view into a height number.','GATE 2026 Geomatics Engineering (GE)',true,2,2,296) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f021','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','Vertical exaggeration in a stereo model increases with the base-height ratio (air base divided by flying height).','Wider spacing between exposures makes hills look steeper than they are. So slopes and dips seen in stereo look too steep.',null,true,2,2,297) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f022','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','The basic elements of photo and image interpretation are tone (or colour), texture, pattern, shape, size, shadow, site and association.','Tone is brightness; texture is the roughness or smoothness of tone. Site and association mean location and neighbouring features.',null,true,3,1,298) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f023','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Sensor quality is described by four resolutions: spatial (smallest ground detail), spectral (number and width of bands), radiometric (brightness levels) and temporal (revisit interval).','Think where, which colour, how many grey shades, and how often. A sensor cannot be best in all four at once.',null,true,3,1,299) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f024','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Radiometric resolution is set by the number of bits: an n-bit sensor records 2^n grey levels, so 8-bit data has 256 levels (0-255).','Each extra bit doubles the number of levels. 10-bit gives 1024 and 11-bit gives 2048.','GATE 2026 Geomatics Engineering (GE)',true,3,1,300) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f025','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Most earth-resource satellites use a near-polar sun-synchronous orbit at about 700-900 km, crossing any place at the same local solar time on every pass.','Same local time means the same sun angle and shadows, so images of different dates can be compared fairly.',null,true,3,1,301) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f026','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','A geostationary satellite orbits above the equator at about 35,786 km with a 24-hour period, so it stays fixed over one spot; used for weather and communication (INSAT).','It turns with the Earth, so it watches the same area all the time. Very high altitude means coarse image detail.',null,true,3,1,302) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f027','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Whiskbroom (across-track) scanners sweep the ground with an oscillating mirror, as in Landsat MSS and TM; pushbroom (along-track) scanners use a line of CCD detectors, as in SPOT and IRS LISS.','Pushbroom has no moving mirror, so each detector looks longer at the ground and gives a cleaner signal.','GATE 2026 Geomatics Engineering (GE)',true,2,2,303) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f028','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Multispectral sensors record a few broad bands; hyperspectral sensors record hundreds of narrow, contiguous bands that can identify individual minerals.','Narrow continuous bands trace the full reflectance curve, so small absorption dips of each mineral become visible.','GATE 2026 Geomatics Engineering (GE)',true,2,2,304) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f029','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','In a standard false colour composite (FCC), near-infrared is shown as red, red as green and green as blue, so healthy vegetation appears red.','Plants reflect near-infrared most, and that band is displayed in red. Clear water appears dark blue to black.','GATE 2026 Geomatics Engineering (GE)',true,3,1,305) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f030','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','On thermal infrared images, water bodies appear cooler (darker) than land by day and warmer (brighter) than land at night.','Water heats and cools slowly (high thermal inertia). Pre-dawn thermal images are preferred for geology as sun-heating effects are least.',null,true,2,2,306) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f031','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Microwave remote sensing works day and night and through cloud; common radar bands in order of increasing wavelength are X (~3 cm), C (~5.6 cm), S (~10 cm) and L (~23 cm).','Long waves pass through cloud droplets. Longer wavelengths such as L-band also penetrate vegetation and dry soil more.',null,true,3,1,307) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f032','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Synthetic aperture radar (SAR) is a side-looking active sensor that uses the platform''s forward motion to imitate a very long antenna, giving fine along-track (azimuth) resolution.','A real antenna that long cannot be carried. So SAR adds up many echoes recorded along the flight path.',null,true,2,2,308) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f033','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','On radar images, smooth surfaces such as calm water look dark (specular reflection), rough surfaces look bright, and buildings act as corner reflectors and look very bright.','A smooth surface bounces the beam away from the antenna like a mirror. Moist soil also returns more signal than dry soil.','GATE 2026 Geomatics Engineering (GE)',true,2,2,309) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f034','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Side-looking radar images of hilly terrain suffer from foreshortening, layover and radar shadow.','Radar measures distance, not angle. A hilltop can be nearer to the radar than its base, so the slope looks squeezed or folded over.',null,true,2,2,310) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f035','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Radar interferometry (InSAR) uses the phase difference between two radar images to derive elevation models and to measure ground movement of centimetre scale.','It is used for land subsidence from groundwater over-pumping, landslide creep and earthquake deformation.',null,true,2,2,311) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f036','geological-assistant','geological-assistant-m1','Digital image processing','Pre-processing corrects an image radiometrically (sensor and atmosphere errors) and geometrically; geometric correction fits the image to map coordinates using ground control points (GCPs).','GCPs are points seen clearly on both image and map, like road crossings. This step must come before enhancement or classification.','GATE 2026 Geomatics Engineering (GE)',true,2,2,312) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f037','geological-assistant','geological-assistant-m1','Digital image processing','Resampling methods are nearest neighbour, bilinear interpolation (4 pixels) and cubic convolution (16 pixels); only nearest neighbour keeps the original pixel values unchanged.','Nearest neighbour just copies the closest pixel, so it is used for classified maps. The others average pixels and look smoother.','GATE 2026 Geomatics Engineering (GE)',true,2,2,313) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f038','geological-assistant','geological-assistant-m1','Digital image processing','Contrast stretching (linear stretch, histogram equalisation) spreads the recorded brightness values over the full display range to make an image clearer.','Raw data often use only a small part of the 0-255 range and look dull. Stretching does not add new information.','GATE 2026 Geomatics Engineering (GE)',true,2,2,314) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f039','geological-assistant','geological-assistant-m1','Digital image processing','Band ratioing (dividing one band by another) reduces brightness differences caused by slope and shadow, and highlights spectral differences between materials.','The same rock on sunny and shaded slopes has a different brightness but nearly the same ratio. Hence ratios suit hilly terrain.',null,true,3,1,315) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f040','geological-assistant','geological-assistant-m1','Digital image processing','NDVI = (NIR - Red) / (NIR + Red); it ranges from -1 to +1, with dense healthy vegetation high positive, bare soil near zero and water negative.','Plants are bright in near-infrared and dark in red, so the difference is large. Water is darker in near-infrared than in red.',null,true,3,1,316) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f041','geological-assistant','geological-assistant-m1','Digital image processing','Supervised classification uses analyst-chosen training sites (e.g. maximum likelihood classifier); unsupervised classification groups pixels automatically into spectral clusters (e.g. ISODATA, K-means).','Supervised: you teach the computer first. Unsupervised: the computer groups first and you name the groups later.',null,true,3,1,317) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f042','geological-assistant','geological-assistant-m1','Digital image processing','Classification accuracy is checked with an error (confusion) matrix against ground truth, giving overall accuracy, producer''s and user''s accuracy and the kappa coefficient.','Kappa tells how much better the map is than a chance result. The diagonal of the matrix holds the correctly classified pixels.','GATE 2026 Geomatics Engineering (GE)',true,2,2,318) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f043','geological-assistant','geological-assistant-m1','Digital image processing','Spatial filtering changes a pixel using its neighbours: low-pass filters smooth an image, high-pass filters sharpen edges, and directional filters enhance linear features of a chosen trend.','Edges are sudden brightness changes (high spatial frequency). Directional filters are a common aid in lineament mapping.','GATE 2026 Geomatics Engineering (GE)',true,2,2,319) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f044','geological-assistant','geological-assistant-m1','Remote sensing in landform and land use mapping','The Anderson (USGS, 1976) land use / land cover scheme is a multi-level classification; its broad Level I classes can be mapped from Landsat-type satellite data.','Finer levels need more detailed images. In India, NRSC maps national land use / land cover using Resourcesat AWiFS and LISS-III data.',null,true,2,2,320) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f045','geological-assistant','geological-assistant-m1','Remote sensing in landform and land use mapping','Drainage texture on images reflects permeability: fine, closely spaced drainage develops on impermeable rocks like shale, and coarse drainage on permeable material like sandstone or gravel.','Where water cannot soak in, more of it runs off and cuts more channels. This helps in both landform and rock-type mapping.',null,true,2,2,321) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
